const p = `<h2>\u06A9\u0627\u0632\u06CC\u0646\u0648 \u0622\u0646\u0644\u0627\u06CC\u0646 \u06A9\u0631\u06CC\u067E\u062A\u0648</h2>
<p>\u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u0647\u0645\u06CC\u0634\u0647 \u0648\u062C\u0648\u062F \u0646\u062F\u0627\u0634\u062A\u0647 \u0627\u0646\u062F\u060C \u0627\u0645\u0627 \u0628\u0647 \u062C\u0631\u0626\u062A \u0645\u06CC \u062A\u0648\u0627\u0646 \u06AF\u0641\u062A \u06A9\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u0627\u0632 \u0632\u0645\u0627\u0646\u06CC \u06A9\u0647 \u0648\u0627\u0631\u062F \u0628\u0627\u0632\u0627\u0631 \u0634\u062F\u0647 \u0627\u0646\u062F \u0628\u0633\u06CC\u0627\u0631 \u0645\u0648\u0631\u062F \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0642\u0631\u0627\u0631 \u06AF\u0631\u0641\u062A\u0647 \u0627\u0646\u062F. \u0648 \u0628\u0647 \u0635\u0648\u0631\u062A \u0645\u0648\u0642\u062A \u0648 \u0645\u0642\u0637\u0639\u06CC \u0646\u06CC\u0633\u062A\u0646\u062F \u0648 \u0627\u06A9\u0646\u0648\u0646 \u062F\u0631 \u0633\u0627\u0644 2023\u060C \u0645\u0627 1000 \u0648 1000 \u0627\u0646\u062A\u062E\u0627\u0628 \u062F\u0627\u0631\u06CC\u0645 - \u0641\u0642\u0637 \u0627\u06CC\u0646 \u0645\u0647\u0645 \u0627\u0633\u062A \u06A9\u0647 \u0634\u0645\u0627 \u0686\u0647 \u0686\u06CC\u0632\u06CC \u0631\u0627 \u062F\u0648\u0633\u062A \u062F\u0627\u0631\u06CC\u062F \u0648 \u0686\u0647 \u06AF\u0632\u06CC\u0646\u0647\u200C\u0647\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A\u06CC \u0631\u0627 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u062F \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0628\u0628\u06CC\u0646\u06CC\u062F.</p>
<p>\u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u0647\u0645\u06CC\u0634\u0647 \u0628\u0647 \u062F\u0646\u0628\u0627\u0644 \u0686\u06CC\u0632 \u0647\u0627\u06CC \u062C\u062F\u06CC\u062F\u06CC \u0647\u0633\u062A\u0646\u062F \u06A9\u0647 \u0628\u0647 \u062A\u062C\u0631\u0628\u0647 \u0628\u0627\u0632\u06CC \u0628\u0633\u06CC\u0627\u0631 \u0628\u0647\u062A\u0631 \u0648 \u062F\u0631 \u062F\u0633\u062A\u0631\u0633\u200C\u062A\u0631 \u06A9\u0645\u06A9 \u0645\u06CC\u200C\u06A9\u0646\u062F. \u0627\u062C\u0627\u0632\u0647 \u062F\u0627\u062F\u0646 \u0628\u0647 \u0628\u0627\u0632\u06CC\u06A9\u0646 \u0628\u0631\u0627\u06CC \u062A\u0645\u0631\u06A9\u0632 \u0628\u0631 \u0644\u0630\u062A \u0645\u0637\u0644\u0642 \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0627\u0632 \u0637\u0631\u06CC\u0642 \u0628\u0627\u0632\u06CC \u0647\u0627 \u0627\u0633\u062A.</p>

<div class="other-info">
  <p>\u0628\u0647 \u0647\u0645\u06CC\u0646 \u062F\u0644\u06CC\u0644 \u0627\u0633\u062A \u06A9\u0647 \u0645\u0627 \u0627\u06A9\u0646\u0648\u0646 \u0642\u0635\u062F \u062F\u0627\u0631\u06CC\u0645 \u0647\u0645\u0647 \u0622\u0646\u0686\u0647 \u0631\u0627 \u06A9\u0647 \u0628\u0627\u06CC\u062F \u062F\u0631 \u0645\u0648\u0631\u062F \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u06A9\u0631\u06CC\u067E\u062A\u0648 \u06CC\u0627 \u0642\u0645\u0627\u0631 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u06CC\u0627 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u06CC\u0627 \u0647\u0631 \u0686\u0647 \u06A9\u0647 \u0645\u06CC \u062E\u0648\u0627\u0647\u06CC\u062F \u0622\u0646 \u0631\u0627 \u0646\u0627\u0645\u06AF\u0630\u0627\u0631\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0628\u0647 \u0634\u0645\u0627 \u0628\u06AF\u0648\u06CC\u06CC\u0645.</p>
  <h2>\u06A9\u0631\u06CC\u067E\u062A\u0648 \u0686\u06CC\u0633\u062A\u061F</h2>
  <p>\u0642\u0628\u0644 \u0627\u0632 \u0628\u062D\u062B \u062F\u0631 \u0645\u0648\u0631\u062F \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648\u06CC\u06CC \u06A9\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0627\u0628\u062A\u062F\u0627 \u0628\u0627\u06CC\u062F \u0628\u062F\u0627\u0646\u06CC\u062F \u06A9\u0647 \u0631\u0645\u0632\u0627\u0631\u0632 \u0686\u06CC\u0633\u062A \u0648 \u0686\u0631\u0627 \u0645\u0631\u062F\u0645 \u062A\u0631\u062C\u06CC\u062D \u0645\u06CC\u200C\u062F\u0647\u0646\u062F \u0627\u0632 \u0627\u06CC\u0646 \u06AF\u0632\u06CC\u0646\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u0647\u0646\u06AF\u0627\u0645 \u0627\u0646\u062C\u0627\u0645 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC \u0645\u0648\u0631\u062F \u0639\u0644\u0627\u0642\u0647 \u062E\u0648\u062F \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u0646\u062F.</p>
  <p>\u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0648 \u0633\u0627\u06CC\u0631 \u0627\u0631\u0632\u0647\u0627\u06CC \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u062F\u0631 \u0686\u0646\u062F \u0633\u0627\u0644 \u06AF\u0630\u0634\u062A\u0647 \u062F\u0631 \u062D\u0627\u0644 \u0631\u0634\u062F \u0628\u0648\u062F\u0647 \u0627\u0646\u062F \u0648 \u0646\u0627\u0645 \u0628\u0632\u0631\u06AF\u06CC \u0628\u0631\u0627\u06CC \u062E\u0648\u062F \u0633\u0627\u062E\u062A\u0647 \u0627\u0646\u062F. \u0648\u0642\u062A\u06CC \u062A\u0627\u0632\u0647 \u0634\u0631\u0648\u0639 \u0634\u062F\u060C \u062E\u0631\u06CC\u062F \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u06CC\u06A9 \u0631\u06CC\u0633\u06A9 \u0628\u0648\u062F \u0648 \u06A9\u0633\u0627\u0646\u06CC \u06A9\u0647 \u0631\u06CC\u0633\u06A9 \u0645\u06CC\u200C\u06A9\u0631\u062F\u0646\u062F\u060C \u0627\u0644\u0627\u0646 \u0627\u0632 \u0622\u0646 \u0633\u0648\u062F \u0645\u06CC\u200C\u0628\u0631\u0646\u062F. Crypto \u0627\u062D\u062A\u0645\u0627\u0644\u0627\u064B \u0627\u0632 \u0628\u0627\u0644\u0627 \u0648 \u067E\u0627\u06CC\u06CC\u0646 \u0631\u0641\u062A\u0646 \u0622\u0646 \u062F\u0631 \u0628\u0627\u0632\u0627\u0631 \u062F\u0631\u0622\u0645\u062F \u0639\u0627\u062F\u0644\u0627\u0646\u0647 \u0627\u06CC \u062F\u0627\u0634\u062A\u0647 \u0627\u0633\u062A \u0648 \u0628\u0647\u062A\u0631\u06CC\u0646 \u0686\u06CC\u0632 \u062F\u0631 \u0645\u0648\u0631\u062F \u0647\u0645\u0647 \u0627\u06CC\u0646\u0647\u0627 \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0622\u0646 \u0631\u0627 \u06A9\u0627\u0645\u0644\u0627\u064B \u0646\u0627\u0634\u0646\u0627\u0633 \u0627\u0646\u062C\u0627\u0645 \u062F\u0647\u06CC\u062F.</p>
  <p>\u0634\u0627\u06CC\u062F \u062F\u0631 \u0622\u0646 \u0632\u0645\u0627\u0646 \u0627\u06CC\u0646 \u06CC\u06A9 \u0631\u06CC\u0633\u06A9 \u0628\u0648\u062F\u060C \u0627\u0645\u0627 \u0627\u0645\u0631\u0648\u0632\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0627\u0632 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0645\u0627\u0646\u0646\u062F \u0647\u0631 \u06AF\u0632\u06CC\u0646\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u062F\u06CC\u06AF\u0631\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F. \u062A\u0639\u062F\u0627\u062F \u06A9\u0645\u06CC \u0622\u0646 \u0631\u0627 \u0646\u0645\u06CC \u067E\u0630\u06CC\u0631\u0646\u062F\u060C \u0627\u0645\u0627 \u06A9\u0627\u0632\u06CC\u0646\u0648 BTC \u06CC\u06A9 \u0645\u0648\u0641\u0642\u06CC\u062A \u0628\u0632\u0631\u06AF \u0627\u0633\u062A \u0648 \u062F\u0631 \u0628\u06CC\u0634 \u0627\u0632 5 \u0633\u0627\u0644 \u06AF\u0630\u0634\u062A\u0647 \u0628\u0647 \u0631\u0634\u062F \u062E\u0648\u062F \u0627\u062F\u0627\u0645\u0647 \u062F\u0627\u062F\u0647 \u0627\u0633\u062A.</p>
  <p>\u0648 \u0622\u0646\u0686\u0647 \u06A9\u0647 \u0628\u06CC\u0634\u062A\u0631 \u062F\u0631 \u0645\u0648\u0631\u062F \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u067E\u0627\u062F\u0627\u0634 \u0633\u067E\u0631\u062F\u0647 \u06CC\u0627 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u06CC\u06A9 \u06AF\u0632\u06CC\u0646\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u0628\u0647 \u0637\u0648\u0631 \u06A9\u0644\u06CC \u0645\u0648\u0631\u062F \u067E\u0633\u0646\u062F \u0627\u0633\u062A\u060C \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0647 \u0631\u0627\u062D\u062A\u06CC \u062D\u0633\u0627\u0628 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u062E\u0648\u062F \u0631\u0627 \u0628\u0647 \u062D\u0633\u0627\u0628 \u0628\u0627\u0646\u06A9\u06CC \u062E\u0648\u062F \u067E\u06CC\u0648\u0646\u062F \u062F\u0647\u06CC\u062F \u0648 \u0628\u0647 \u0635\u0646\u062F\u0648\u0642 \u0627\u0631\u0632 \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u0628\u0631\u062A\u0631 \u062E\u0648\u062F \u062F\u0633\u062A\u0631\u0633\u06CC \u0645\u0633\u062A\u0642\u06CC\u0645 \u0648 \u0641\u0648\u0631\u06CC \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u06CC\u062F.</p>

  <h2>\u0622\u06CC\u0627 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0627\u0632 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u062F\u0631 \u062A\u0645\u0627\u0645 \u0633\u0627\u06CC\u062A \u0647\u0627\u06CC \u0642\u0645\u0627\u0631 \u0622\u0646\u0644\u0627\u06CC\u0646 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F\u061F</h2>
  <p>\u0647\u0645\u0647 \u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u0622\u0631\u0632\u0648 \u062F\u0627\u0631\u0646\u062F \u06A9\u0647 \u062A\u0645\u0627\u0645 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u0645\u062E\u062A\u0644\u0641\u06CC \u06A9\u0647 \u067E\u06CC\u062F\u0627 \u0645\u06CC \u06A9\u0646\u0646\u062F \u0628\u0647 \u0622\u0646\u0647\u0627 \u0627\u0645\u06A9\u0627\u0646 \u062F\u0647\u062F \u0627\u0632 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0648 \u0633\u0627\u06CC\u0631 \u0627\u0631\u0632\u0647\u0627\u06CC \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u0628\u0631\u0627\u06CC \u0648\u0627\u0631\u06CC\u0632 \u0648 \u0628\u0631\u062F\u0627\u0634\u062A \u062E\u0648\u062F \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u0646\u062F. \u0645\u062A\u0623\u0633\u0641\u0627\u0646\u0647\u060C \u062D\u0642\u06CC\u0642\u062A \u063A\u0645 \u0627\u0646\u06AF\u06CC\u0632 \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u062A\u0639\u062F\u0627\u062F \u06A9\u0645\u06CC \u0627\u0632 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0622\u0646 \u0631\u0627 \u0645\u06CC \u067E\u0630\u06CC\u0631\u0646\u062F. \u0627\u0645\u0627 \u062E\u0628\u0631 \u062E\u0648\u0628 \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0628\u0631\u062A\u0631\u06CC\u0646 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u062F\u0627\u0631\u0627\u06CC \u06CC\u06A9 \u0631\u0645\u0632\u0627\u0631\u0632 \u0647\u0633\u062A\u0646\u062F \u06A9\u0647 \u062D\u062F\u0627\u0642\u0644 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0631\u0627\u06CC \u0633\u067E\u0631\u062F\u0647 \u06AF\u0630\u0627\u0631\u06CC \u0627\u0632 \u0622\u0646 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F. \u0648\u0642\u062A\u06CC \u0635\u062D\u0628\u062A \u0627\u0632 \u0628\u0631\u062F\u0627\u0634\u062A \u0628\u0647 \u0645\u06CC\u0627\u0646 \u0645\u06CC \u0622\u06CC\u062F\u060C \u067E\u06CC\u062F\u0627 \u06A9\u0631\u062F\u0646 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u06A9\u0645\u06CC \u0633\u062E\u062A\u200C\u062A\u0631 \u0627\u0633\u062A. \u0628\u0647 \u0627\u062D\u062A\u0645\u0627\u0644 \u0632\u06CC\u0627\u062F\u060C \u0628\u0627\u06CC\u062F \u06CC\u06A9\u06CC \u0627\u0632 \u06AF\u0632\u06CC\u0646\u0647 \u0647\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u062F\u06CC\u06AF\u0631 \u0631\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F. \u06CC\u0627\u0641\u062A \u0634\u062F\u0647 \u062A\u0631\u06CC\u0646 \u06AF\u0632\u06CC\u0646\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u0628\u0631\u0627\u06CC \u062A\u0631\u06A9\u06CC\u0628 \u0628\u0627 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0648 \u06A9\u0631\u06CC\u067E\u062A\u0648\u060C \u0627\u0646\u062A\u0642\u0627\u0644 \u0628\u0627\u0646\u06A9\u06CC \u0645\u0633\u062A\u0642\u06CC\u0645 \u0628\u0647 \u062D\u0633\u0627\u0628 \u0628\u0627\u0646\u06A9\u06CC \u0634\u0645\u0627 \u0627\u0633\u062A.</p>
  <p>\u0628\u0631\u0627\u06CC \u062A\u0627\u0632\u0647\u200C\u06A9\u0627\u0631\u0647\u0627\u060C \u0686\u0646\u062F \u0646\u0627\u0645 \u0628\u0631\u0627\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u062F\u06CC\u06AF\u0631 \u0642\u0631\u0627\u0631 \u0645\u06CC\u200C\u062F\u0647\u06CC\u0645 \u062A\u0627 \u0627\u06AF\u0631 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u062F \u0633\u0627\u06CC\u062A\u200C\u0647\u0627\u06CC \u0634\u0631\u0637\u200C\u0628\u0646\u062F\u06CC \u0631\u0627 \u0627\u0645\u062A\u062D\u0627\u0646 \u06A9\u0646\u06CC\u062F \u06A9\u0647 \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0645\u06CC\u200C\u067E\u0630\u06CC\u0631\u0646\u062F\u060C \u0628\u0631\u0631\u0633\u06CC \u06A9\u0646\u06CC\u062F. \u0645\u0627 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u062F\u0648\u062C\u060C \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0634\u06CC\u0628\u0627 \u0648 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0633\u0648\u0644\u0627\u0646\u0627 \u062F\u0627\u0631\u06CC\u0645 \u0648 \u0647\u0645\u0647 \u0622\u0646\u0647\u0627 \u0627\u0631\u0632\u0634 \u0648\u0642\u062A \u0634\u0645\u0627 \u0631\u0627 \u062F\u0627\u0631\u0646\u062F. \u0622\u0646\u0647\u0627 \u0647\u06CC\u062C\u0627\u0646\u06CC \u0631\u0627 \u06A9\u0647 \u0647\u0645\u0647 \u0634\u0645\u0627 \u0628\u0647 \u062F\u0646\u0628\u0627\u0644 \u0622\u0646 \u0647\u0633\u062A\u06CC\u062F \u0628\u0647 \u0627\u0631\u0645\u063A\u0627\u0646 \u062E\u0648\u0627\u0647\u0646\u062F \u0622\u0648\u0631\u062F. \u0634\u0645\u0627 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0627 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u067E\u0631\u062F\u0627\u062E\u062A \u06A9\u0646\u06CC\u062F \u2013 \u0648 \u0628\u0647\u062A\u0631\u06CC\u0646 \u0628\u062E\u0634 \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0647\u0645\u0647 \u0622\u0646\u0647\u0627 \u0628\u0631\u0627\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u062E\u0648\u062F \u0648 \u067E\u06CC\u0648\u0633\u062A\u0646 \u0628\u0647 \u062F\u0646\u06CC\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0642\u0645\u0627\u0631 \u0628\u0647 \u0634\u0645\u0627 \u06CC\u06A9 \u067E\u0627\u062F\u0627\u0634 \u0633\u067E\u0631\u062F\u0647 \u0639\u0627\u0644\u06CC \u0645\u06CC \u062F\u0647\u0646\u062F.</p>
  
  <h2>\u0645\u0632\u06CC\u062A \u0647\u0627\u06CC \u0642\u0645\u0627\u0631 \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0686\u06CC\u0633\u062A\u061F</h2>
  <ul>
    <li>\u0646\u0627\u0634\u0646\u0627\u0633 \u0628\u0648\u062F\u0646 \u2013 \u0647\u0646\u06AF\u0627\u0645 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0631\u0645\u0632\u0646\u06AF\u0627\u0631\u06CC \u062F\u0631 \u0628\u0627\u0632\u0627\u0631 \u0622\u0646\u0644\u0627\u06CC\u0646\u060C \u0646\u06CC\u0627\u0632\u06CC \u0628\u0647 \u0627\u0631\u0627\u0626\u0647 \u0627\u0637\u0644\u0627\u0639\u0627\u062A\u06CC \u0646\u062F\u0627\u0631\u06CC\u062F \u06A9\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u062F \u0628\u0647 \u0634\u0645\u0627 \u0645\u0646\u062A\u0647\u06CC \u0634\u0648\u062F. \u0634\u0645\u0627 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F 100% \u067E\u0634\u062A \u0635\u0641\u062D\u0647 \u06A9\u0627\u0645\u067E\u06CC\u0648\u062A\u0631 \u067E\u0646\u0647\u0627\u0646 \u0634\u0648\u06CC\u062F \u0648 \u0647\u0631\u06AF\u0632 \u0628\u0647 \u0627\u0646\u062F\u0627\u0632\u0647 \u0646\u0627\u0645 \u06A9\u0648\u0686\u06A9 \u062E\u0648\u062F \u062A\u0633\u0644\u06CC\u0645 \u0646\u0634\u0648\u06CC\u062F. \u0627\u06CC\u0646 \u0628\u0647\u062A\u0631\u06CC\u0646 \u0646\u0642\u0637\u0647 \u0641\u0631\u0648\u0634 \u0628\u0631\u0627\u06CC \u0627\u06CC\u0646 \u0646\u0648\u0639 \u06AF\u0632\u06CC\u0646\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u0628\u0631\u0627\u06CC \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0633\u062A.</li>
    <li>\u062F\u0633\u062A\u0631\u0633\u06CC \u062F\u0631 \u0633\u0631\u0627\u0633\u0631 \u062C\u0647\u0627\u0646 - \u0647\u0645\u0627\u0646\u0637\u0648\u0631 \u06A9\u0647 \u0645\u06CC \u062F\u0627\u0646\u06CC\u0645\u060C \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u06AF\u0632\u06CC\u0646\u0647 \u0647\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u0641\u0642\u0637 \u0628\u0631\u0627\u06CC \u0628\u0631\u062E\u06CC \u062F\u0631 \u062F\u0633\u062A\u0631\u0633 \u0647\u0633\u062A\u0646\u062F\u060C \u0646\u0647 \u0647\u0645\u0647\u060C \u0648 \u0627\u06CC\u0646 \u0645\u06CC \u062A\u0648\u0627\u0646\u062F \u0628\u0633\u06CC\u0627\u0631 \u062E\u0633\u062A\u0647 \u06A9\u0646\u0646\u062F\u0647 \u0628\u0627\u0634\u062F \u0648 \u0628\u0631\u0627\u06CC \u0628\u0631\u062E\u06CC \u0627\u0632 \u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u062F\u0631 \u0628\u0631\u062E\u06CC \u06A9\u0634\u0648\u0631\u0647\u0627 \u0686\u0627\u0644\u0634 \u0628\u0631\u0627\u0646\u06AF\u06CC\u0632 \u0628\u0627\u0634\u062F - \u0632\u06CC\u0631\u0627 \u0645\u062D\u062F\u0648\u062F\u06CC\u062A\u200C\u0647\u0627\u06CC \u0622\u0646\u0647\u0627 \u062F\u0631 \u06AF\u0632\u06CC\u0646\u0647 \u0647\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u0628\u0647 \u0634\u062F\u062A \u0645\u0627\u0646\u0639 \u0627\u0632 \u0628\u0627\u0632\u06CC \u0622\u0646\u0647\u0627 \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0648 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u0646\u062F \u062F\u0631 \u0622\u0646\u0647\u0627 \u0628\u0627\u0632\u06CC \u06A9\u0646\u0646\u062F \u0645\u06CC\u200C\u0634\u0648\u062F. \u0628\u0627 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0648 \u0633\u0627\u06CC\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648\u060C \u0622\u0646\u0647\u0627 \u0627\u06CC\u0646 \u0645\u062D\u062F\u0648\u062F\u06CC\u062A \u0631\u0627 \u062D\u0630\u0641 \u062E\u0648\u0627\u0647\u0646\u062F \u06A9\u0631\u062F \u0648 \u062F\u06CC\u06AF\u0631 \u0645\u062C\u0628\u0648\u0631 \u0646\u06CC\u0633\u062A\u0646\u062F \u0628\u0631\u0627\u06CC \u0633\u0631\u06AF\u0631\u0645\u06CC \u062E\u0648\u062F \u062F\u0631 \u062C\u0627\u06CC \u062F\u06CC\u06AF\u0631\u06CC \u062C\u0633\u062A\u062C\u0648 \u06A9\u0646\u0646\u062F.</li>
    <li>\u062A\u0623\u06CC\u06CC\u062F -\u0636\u062F \u062D\u0627\u0644 \u06CC\u06A9 \u0645\u0647\u0645\u0627\u0646\u06CC \u0632\u0645\u0627\u0646\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0634\u0645\u0627 \u0628\u0627\u06CC\u062F \u0627\u0637\u0644\u0627\u0639\u0627\u062A \u0632\u06CC\u0627\u062F\u06CC \u0631\u0627 \u0628\u0631\u0627\u06CC \u062F\u0633\u062A\u0631\u0633\u06CC \u0628\u0647 \u0633\u0631\u06AF\u0631\u0645\u06CC \u067E\u0631 \u06A9\u0646\u06CC\u062F. \u067E\u0627\u0633\u062E \u0633\u0627\u062F\u0647\u060C \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0631\u0645\u0632\u0646\u06AF\u0627\u0631\u06CC \u0627\u0633\u062A \u0648 \u062F\u06CC\u06AF\u0631 \u0646\u06CC\u0627\u0632\u06CC \u0628\u0647 \u062A\u062C\u0631\u0628\u0647 \u0622\u0646 \u0646\u062E\u0648\u0627\u0647\u06CC\u062F \u062F\u0627\u0634\u062A.</li>
    <li>\u06A9\u0627\u0631\u0645\u0632\u062F \u062A\u0631\u0627\u06A9\u0646\u0634 - \u0628\u0633\u06CC\u0627\u0631 \u062E\u0648\u0628\u060C \u0645\u0627 \u0645\u06CC\u200C\u062F\u0627\u0646\u06CC\u0645 \u06A9\u0647 \u0647\u0645\u0647 \u0628\u0627\u06CC\u062F \u067E\u0648\u0644 \u062F\u0631 \u0628\u06CC\u0627\u0648\u0631\u0646\u062F \u0648 \u0627\u06CC\u0646 \u0647\u0645\u0647 \u0686\u06CC\u0632\u06CC \u0646\u06CC\u0633\u062A \u06A9\u0647 \u062A\u0648\u0633\u0637 \u062A\u0628\u0644\u06CC\u063A\u0627\u062A \u0648 \u063A\u06CC\u0631\u0647 \u067E\u0648\u0634\u0634 \u062F\u0627\u062F\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F\u060C \u06A9\u0647 \u062F\u0631 \u067E\u0633\u200C\u0632\u0645\u06CC\u0646\u0647 \u0627\u062C\u0631\u0627 \u0645\u06CC\u200C\u0634\u0648\u0646\u062F \u0648 \u06A9\u0627\u0631\u0645\u0632\u062F\u0647\u0627\u06CC \u0627\u0633\u062A\u0627\u0646\u062F\u0627\u0631\u062F\u06CC \u06A9\u0647 \u0628\u0627 \u06CC\u06A9 \u062A\u0631\u0627\u06A9\u0646\u0634 \u0627\u0631\u0627\u0626\u0647 \u0645\u06CC\u200C\u0634\u0648\u062F. \u0627\u0645\u0627 \u0645\u0627 \u0647\u0645\u0686\u0646\u06CC\u0646 \u0645\u06CC\u200C\u062F\u0627\u0646\u06CC\u0645 \u06A9\u0647 \u0628\u0631\u062E\u06CC \u0627\u0632 \u06AF\u0632\u06CC\u0646\u0647 \u0647\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u062F\u0648\u0633\u062A \u062F\u0627\u0631\u0646\u062F \u0647\u0632\u06CC\u0646\u0647 \u0647\u0627\u06CC\u06CC \u0631\u0627 \u06A9\u0647 \u0627\u0632 \u0645\u0634\u062A\u0631\u06CC\u0627\u0646 \u062E\u0648\u062F \u0647\u0646\u06AF\u0627\u0645 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u062E\u062F\u0645\u0627\u062A \u062E\u0648\u062F \u062F\u0631\u06CC\u0627\u0641\u062A \u0645\u06CC \u06A9\u0646\u0646\u062F\u060C \u0633\u0646\u06AF\u06CC\u0646 \u06A9\u0646\u0646\u062F. \u0627\u06AF\u0631 \u0627\u0632 \u0631\u0645\u0632\u0646\u06AF\u0627\u0631\u06CC \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u06CC\u06A9 \u06AF\u0632\u06CC\u0646\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0627\u06CC\u0646 \u0645\u0634\u06A9\u0644 \u0631\u0627 \u067E\u06CC\u062F\u0627 \u0646\u062E\u0648\u0627\u0647\u06CC\u062F \u06A9\u0631\u062F.</li>
  </ul>
  
  <h2>\u0645\u0639\u0627\u06CC\u0628 \u0642\u0645\u0627\u0631 \u06A9\u0631\u06CC\u067E\u062A\u0648</h2>
  <ul>
    <li>\u0628\u062F\u0648\u0646 \u0628\u0627\u0632\u067E\u0631\u062F\u0627\u062E\u062A/\u0628\u0631\u06AF\u0634\u062A - \u0645\u062A\u0623\u0633\u0641\u0627\u0646\u0647\u060C \u0647\u0646\u06AF\u0627\u0645 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0627\u06CC\u0646 \u06AF\u0632\u06CC\u0646\u0647 \u067E\u0631\u062F\u0627\u062E\u062A\u060C \u0647\u06CC\u0686 \u0628\u0627\u0632\u067E\u0633 \u06AF\u06CC\u0631\u06CC \u0646\u062F\u0627\u0631\u06CC\u062F. \u0647\u0646\u06AF\u0627\u0645\u06CC \u06A9\u0647 \u062A\u0631\u0627\u06A9\u0646\u0634 \u062F\u0631 \u062D\u0633\u0627\u0628 \u0634\u0645\u0627 \u062A\u0623\u06CC\u06CC\u062F \u0634\u062F \u0648 \u06A9\u06CC\u0641 \u067E\u0648\u0644 \u0634\u0645\u0627 \u0631\u0627 \u062A\u0631\u06A9 \u06A9\u0631\u062F\u060C \u062A\u0645\u0627\u0645 \u0627\u0633\u062A. \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0645\u0637\u0645\u0626\u0646 \u0634\u0648\u06CC\u062F \u06A9\u0647 \u0628\u0631\u0631\u0633\u06CC \u067E\u06CC\u0634\u06CC\u0646\u0647 \u062E\u0648\u062F \u0631\u0627 \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u06CC\u0627 \u0633\u0627\u06CC\u062A \u0642\u0645\u0627\u0631 \u0622\u0646\u0644\u0627\u06CC\u0646\u06CC \u06A9\u0647 \u0645\u06CC \u062E\u0648\u0627\u0647\u06CC\u062F \u0632\u0645\u0627\u0646 \u0648 \u067E\u0648\u0644 \u062E\u0648\u062F \u0631\u0627 \u062F\u0631 \u0622\u0646 \u062E\u0631\u062C \u06A9\u0646\u06CC\u062F \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC \u062F\u0647\u06CC\u062F\u060C \u0632\u06CC\u0631\u0627 \u0627\u0645\u0646\u06CC\u062A \u0645\u0634\u0627\u0628\u0647 \u06A9\u0627\u0631\u062A \u0647\u0627\u06CC \u0627\u0639\u062A\u0628\u0627\u0631\u06CC \u0648 \u0633\u0627\u06CC\u0631 \u0631\u0648\u0634 \u0647\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u0633\u0646\u062A\u06CC \u0631\u0627 \u0646\u062F\u0627\u0631\u06CC\u062F.</li>
    <li>"\u0647\u0645\u06CC\u0634\u0647 \u062D\u0642 \u0628\u0627 \u0645\u0634\u062A\u0631\u06CC \u0627\u0633\u062A" \u062F\u0631 \u06A9\u0627\u0631 \u0646\u06CC\u0633\u062A - \u0648\u0642\u062A\u06CC \u0628\u0647 \u0645\u0634\u06A9\u0644\u0627\u062A \u0645\u0631\u0628\u0648\u0637 \u0628\u0647 \u062A\u0631\u0627\u06A9\u0646\u0634 \u0647\u0627 \u0645\u06CC \u0631\u0633\u062F\u060C \u062E\u062F\u0645\u0627\u062A \u0645\u0634\u062A\u0631\u06CC \u0622\u0646\u0647\u0627 \u0628\u0647\u062A\u0631\u06CC\u0646 \u0646\u0628\u0648\u062F\u0647 \u0627\u0633\u062A. \u0622\u0646\u0647\u0627 \u0627\u0631\u062A\u0628\u0627\u0637 \u062E\u0648\u0628\u06CC \u0628\u0627 \u0647\u0645\u0647 \u0645\u0634\u062A\u0631\u06CC\u0627\u0646 \u062E\u0648\u062F \u0628\u0631\u0642\u0631\u0627\u0631 \u0645\u06CC \u06A9\u0646\u0646\u062F \u0648 \u0634\u0645\u0627 \u0642\u0631\u0627\u0631 \u0646\u06CC\u0633\u062A \u0645\u0633\u0627\u06CC\u0650\u0644 \u0631\u0627 \u0628\u0647 \u062A\u0646\u0647\u0627\u06CC\u06CC \u0645\u0631\u062A\u0628 \u06A9\u0646\u06CC\u062F. \u0627\u0645\u0627 \u0634\u0627\u0646\u0633 \u0628\u0627\u0632\u06AF\u0631\u062F\u0627\u0646\u062F\u0646 \u067E\u0648\u0644 \u067E\u0633 \u0627\u0632 \u062E\u0631\u0648\u062C \u0627\u0632 \u062D\u0633\u0627\u0628 \u0634\u0645\u0627 \u0628\u0633\u06CC\u0627\u0631 \u06A9\u0645 \u0627\u0633\u062A. \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0628\u0627\u06CC\u062F \u0645\u0637\u0645\u0626\u0646 \u0634\u0648\u06CC\u062F \u06A9\u0647 \u0686\u0647 \u0632\u0645\u0627\u0646\u06CC \u0627\u0632 \u0622\u0646 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0645\u06CC\u200C\u06A9\u0646\u06CC\u062F \u0648 \u0686\u0642\u062F\u0631 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u062F \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F \u0648 \u0627\u06CC\u0646\u06A9\u0647 \u0648\u0627\u0642\u0639\u0627\u064B \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0647 \u0634\u062E\u0635/\u0634\u0631\u06A9\u062A\u06CC \u06A9\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u0645\u06CC\u200C\u06A9\u0646\u06CC\u062F \u0627\u0639\u062A\u0645\u0627\u062F \u06A9\u0646\u06CC\u062F.</li>
  </ul>
  
  <h2>\u0686\u06AF\u0648\u0646\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u0645 \u0645\u0637\u0645\u0626\u0646 \u0634\u0648\u0645 \u06A9\u0647 \u0633\u0627\u06CC\u062A \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0622\u0646\u0644\u0627\u06CC\u0646 \u0627\u0645\u0646 \u0627\u0633\u062A\u061F</h2>
  <p>\u0627\u06A9\u062B\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u0627\u0645\u0631\u0648\u0632\u0647 \u0627\u06CC\u0645\u0646 \u0647\u0633\u062A\u0646\u062F \u0648 \u0646\u06CC\u0627\u0632\u06CC \u0646\u06CC\u0633\u062A \u0646\u06AF\u0631\u0627\u0646 \u0635\u0631\u0641 \u0648\u0642\u062A \u062E\u0648\u062F \u062F\u0631 \u0622\u0646\u0647\u0627 \u0628\u0627\u0634\u06CC\u062F. \u0628\u0627 \u0627\u06CC\u0646 \u062D\u0627\u0644\u060C \u0628\u0631\u062E\u06CC \u0627\u0632 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0647\u0633\u062A\u0646\u062F \u06A9\u0647 \u0628\u0647\u062A\u0631\u06CC\u0646 \u0639\u0644\u0627\u0642\u0647 \u0634\u0645\u0627 \u0631\u0627 \u062F\u0631 \u0646\u0638\u0631 \u0646\u0645\u06CC\u06AF\u06CC\u0631\u0646\u062F. \u0628\u0647 \u0647\u0645\u06CC\u0646 \u062F\u0644\u06CC\u0644 \u0627\u0633\u062A \u06A9\u0647 \u0634\u0645\u0627 \u0647\u0645\u06CC\u0634\u0647 \u0628\u0627\u06CC\u062F \u067E\u0633\u200C\u0632\u0645\u06CC\u0646\u0647 \u062E\u0648\u062F \u0631\u0627 \u0628\u0631\u0631\u0633\u06CC \u06A9\u0646\u06CC\u062F\u060C \u062D\u062A\u06CC \u0648\u0642\u062A\u06CC \u0635\u062D\u0628\u062A \u0627\u0632 \u0642\u0645\u0627\u0631 \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0628\u0647 \u0645\u06CC\u0627\u0646 \u0645\u06CC\u200C\u0622\u06CC\u062F. \u06CC\u0627 \u062D\u062F\u0627\u0642\u0644 \u0628\u0627\u06CC\u062F \u0628\u06AF\u0648\u06CC\u06CC\u0645 \u06A9\u0647 \u0622\u06CC\u0627 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u062F \u0627\u0632 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0628\u0631\u0627\u06CC \u0642\u0645\u0627\u0631 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F. \u0627\u0645\u0646\u06CC\u062A \u0627\u0636\u0627\u0641\u06CC \u0648\u062C\u0648\u062F \u0646\u062F\u0627\u0631\u062F \u0648 \u0648\u0642\u062A\u06CC \u067E\u0648\u0644 \u0627\u0632 \u06A9\u06CC\u0641 \u0634\u0645\u0627 \u062E\u0627\u0631\u062C \u0645\u06CC \u0634\u0648\u062F\u060C \u0634\u0627\u0646\u0633 \u0632\u06CC\u0627\u062F\u06CC \u0628\u0631\u0627\u06CC \u067E\u0633 \u06AF\u0631\u0641\u062A\u0646 \u067E\u0648\u0644 \u0646\u062F\u0627\u0631\u06CC\u062F.</p>
  <p>\u062E\u0648\u0634\u0628\u062E\u062A\u0627\u0646\u0647 \u0631\u0627\u0647\u200C\u0647\u0627\u06CC\u06CC \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F \u06A9\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u062F\u0631\u06CC\u0627\u0628\u06CC\u062F \u06A9\u0647 \u0622\u06CC\u0627 \u0648\u0627\u0642\u0639\u0627\u064B \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u06CC\u06CC \u06A9\u0647 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u062F \u0648\u0642\u062A \u062E\u0648\u062F \u0631\u0627 \u062F\u0631 \u0622\u0646 \u0635\u0631\u0641 \u06A9\u0646\u06CC\u062F \u0627\u0639\u062A\u0645\u0627\u062F \u06A9\u0646\u06CC\u062F. \u0628\u0647\u062A\u0631\u06CC\u0646 \u0631\u0627\u0647 \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0628\u0631\u0631\u0633\u06CC \u06A9\u0646\u06CC\u062F \u0622\u06CC\u0627 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u062F\u0627\u0631\u0627\u06CC \u0645\u062C\u0648\u0632 \u0645\u0639\u062A\u0628\u0631 \u0628\u0631\u0627\u06CC \u0642\u0645\u0627\u0631 \u0622\u0646\u0644\u0627\u06CC\u0646 \u0627\u0633\u062A \u06CC\u0627 \u062E\u06CC\u0631. \u0647\u0645\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0628\u0631\u0627\u06CC \u0627\u062C\u0631\u0627\u06CC \u0642\u0627\u0646\u0648\u0646\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648 \u062E\u0648\u062F \u0628\u0647 \u0627\u06CC\u0646 \u0646\u06CC\u0627\u0632 \u062F\u0627\u0631\u0646\u062F\u060C \u0648 \u0631\u0627\u06CC\u06AF\u0627\u0646 \u0646\u06CC\u0633\u062A\u060C \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0686\u06CC\u0632\u06CC \u0646\u06CC\u0633\u062A \u06A9\u0647 \u067E\u0646\u0647\u0627\u0646 \u06A9\u0646\u0646\u062F. \u0628\u0631\u062E\u06CC \u0627\u0632 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u062A\u0631\u062C\u06CC\u062D \u0645\u06CC \u062F\u0647\u0646\u062F \u0628\u06CC\u0634 \u0627\u0632 \u06CC\u06A9\u06CC \u0627\u0632 \u0627\u06CC\u0646 \u0645\u062C\u0648\u0632\u0647\u0627 \u0631\u0627 \u062F\u0631\u06CC\u0627\u0641\u062A \u06A9\u0646\u0646\u062F. \u0627\u06CC\u0646 \u06CC\u06A9 \u067E\u0631\u0686\u0645 \u0642\u0631\u0645\u0632 \u0628\u0631\u0627\u06CC \u0628\u0631\u062E\u06CC \u0627\u0633\u062A \u0648 \u0645\u0627 \u0627\u06CC\u0646\u062C\u0627 \u0647\u0633\u062A\u06CC\u0645 \u062A\u0627 \u0628\u0647 \u0634\u0645\u0627 \u0628\u06AF\u0648\u06CC\u06CC\u0645 \u06A9\u0647 \u067E\u0631\u0686\u0645 \u0642\u0631\u0645\u0632 \u0646\u06CC\u0633\u062A. \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0647\u0631 \u062A\u0639\u062F\u0627\u062F \u0645\u062C\u0648\u0632 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F\u060C \u0627\u0645\u0627 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u06CC\u06A9 \u0645\u062C\u0648\u0632 \u0646\u06CC\u0632 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F.</p>
  <p>\u0647\u0645\u0686\u0646\u06CC\u0646\u060C \u062C\u0633\u062A\u062C\u0648 \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0628\u0631\u0627\u06CC \u0628\u0631\u0631\u0633\u06CC \u0622\u0646\u0686\u0647 \u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u062F\u06CC\u06AF\u0631 \u0645\u06CC\u200C\u06AF\u0648\u06CC\u0646\u062F \u0647\u0645\u06CC\u0634\u0647 \u0627\u06CC\u062F\u0647 \u062E\u0648\u0628\u06CC \u0627\u0633\u062A. \u0627\u06AF\u0631 \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0646\u0627\u0639\u0627\u062F\u0644\u0627\u0646\u0647 \u0628\u0627\u0634\u062F\u060C \u0634\u0645\u0627 \u0627\u0648\u0644\u06CC\u0646 \u06A9\u0633\u06CC \u0646\u06CC\u0633\u062A\u06CC\u062F \u06A9\u0647 \u0622\u0646\u0647\u0627 \u0627\u06CC\u0646 \u06A9\u0627\u0631 \u0631\u0627 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC \u062F\u0647\u0646\u062F - \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0646\u0648\u0639\u06CC \u0628\u0631\u0631\u0633\u06CC \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F \u06A9\u0647 \u0628\u0647 \u0634\u0645\u0627 \u062F\u0631\u0628\u0627\u0631\u0647 \u0622\u0646\u0686\u0647 \u0627\u062A\u0641\u0627\u0642 \u0627\u0641\u062A\u0627\u062F\u0647 \u0648 \u0622\u0646\u0686\u0647 \u062F\u0631 \u0645\u0648\u0631\u062F \u0622\u0646 \u0627\u0646\u062C\u0627\u0645 \u0634\u062F\u0647 \u0627\u0633\u062A \u0645\u06CC \u06AF\u0648\u06CC\u062F. \u0628\u0647\u062A\u0631\u06CC\u0646 \u0642\u0636\u0627\u0648\u062A \u062E\u0648\u062F \u0631\u0627 \u0628\u0647 \u06A9\u0627\u0631 \u0628\u0628\u0631\u06CC\u062F\u060C \u0648 \u0627\u06AF\u0631 \u0686\u06CC\u0632\u06CC \u062F\u0631 \u0645\u0648\u0631\u062F \u0633\u0627\u06CC\u062A \u0642\u0645\u0627\u0631 \u0627\u062D\u0633\u0627\u0633 \u0645\u06CC\u200C\u0634\u0648\u062F\u060C \u0686\u06CC\u0632\u0647\u0627\u06CC \u0628\u06CC\u0634\u062A\u0631\u06CC \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F. \u06CC\u06A9\u06CC \u062F\u06CC\u06AF\u0631 \u0631\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F\u060C \u0648 \u0646\u06CC\u0627\u0632\u06CC \u0628\u0647 \u0642\u0645\u0627\u0631 \u0628\u0627 \u0633\u0631\u0646\u0648\u0634\u062A \u0646\u06CC\u0633\u062A.</p>

  <h2>\u0627\u06AF\u0631 \u0628\u0627 \u0627\u0631\u0632 \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u0633\u067E\u0631\u062F\u0647 \u06AF\u0630\u0627\u0631\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0647\u0646\u0648\u0632 \u0647\u0645 \u067E\u0627\u062F\u0627\u0634 \u062F\u0631\u06CC\u0627\u0641\u062A \u0645\u06CC \u06A9\u0646\u06CC\u062F\u061F</h2>
  <p>\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u0645 \u0628\u06AF\u0648\u06CC\u06CC\u0645 \u06A9\u0647 \u0627\u06CC\u0646 \u062A\u062C\u0631\u0628\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u060C \u0647\u06CC\u062C\u0627\u0646\u060C \u0633\u0631\u06AF\u0631\u0645\u06CC \u0648 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u0631\u0627 \u0628\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0645\u062E\u062A\u0644\u0641 \u0645\u06CC\u200C\u0622\u0648\u0631\u062F\u060C \u0627\u0645\u0627 \u0647\u0645\u0647 \u0645\u06CC\u200C\u062F\u0627\u0646\u06CC\u0645 \u06A9\u0647 \u0627\u06CC\u0646 \u06CC\u06A9 \u062F\u0631\u0648\u063A \u0627\u0633\u062A. \u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u062C\u0648\u0627\u06CC\u0632 \u0648 \u067E\u0627\u062F\u0627\u0634\u200C\u0647\u0627\u06CC \u0632\u06CC\u0627\u062F\u06CC \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u0646\u062F \u062A\u0627 \u0628\u0647 \u0622\u0646\u0647\u0627 \u062F\u0631 \u0631\u0627\u0647 \u0631\u0633\u06CC\u062F\u0646 \u0628\u0647 \u067E\u06CC\u0631\u0648\u0632\u06CC \u0628\u0632\u0631\u06AF \u06A9\u0645\u06A9 \u06A9\u0646\u062F. \u062C\u0648\u0627\u06CC\u0632 \u062F\u0642\u06CC\u0642\u0627\u064B \u0645\u0627\u0646\u0646\u062F \u067E\u0648\u0644 \u0631\u0627\u06CC\u06AF\u0627\u0646 \u0647\u0633\u062A\u0646\u062F \u0648 \u0641\u0642\u0637 \u0642\u0628\u0644 \u0627\u0632 \u0627\u06CC\u0646\u06A9\u0647 \u0622\u0646\u0647\u0627 \u0631\u0627 \u0628\u067E\u0630\u06CC\u0631\u06CC\u062F \u0645\u0631\u0627\u0642\u0628 \u0634\u0631\u0627\u06CC\u0637\u06CC \u0628\u0627\u0634\u06CC\u062F \u06A9\u0647 \u0628\u0627 \u067E\u0627\u062F\u0627\u0634 \u0647\u0627 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062A.</p>
  <p>\u0641\u0631\u0636 \u06A9\u0646\u06CC\u062F \u0642\u0631\u0627\u0631 \u0627\u0633\u062A \u0628\u0627 \u0627\u0631\u0632 \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u0633\u067E\u0631\u062F\u0647 \u06AF\u0630\u0627\u0631\u06CC \u06A9\u0646\u06CC\u062F. \u062F\u0631 \u0627\u06CC\u0646 \u0645\u0648\u0631\u062F\u060C \u062A\u062C\u0631\u0628\u0647 \u06A9\u0627\u0631\u0628\u0631 \u0628\u0647 \u0645\u0627 \u0645\u06CC \u06AF\u0648\u06CC\u062F \u06A9\u0647 \u067E\u0627\u062F\u0627\u0634 \u0647\u0627 \u062C\u0632\u0626\u06CC \u0647\u0633\u062A\u0646\u062F \u0627\u0645\u0627 \u0628\u0631\u0627\u06CC \u0622\u0646\u0686\u0647 \u062F\u0631\u06CC\u0627\u0641\u062A \u0645\u06CC \u06A9\u0646\u06CC\u062F \u0628\u062F \u0646\u06CC\u0633\u062A\u0646\u062F. \u0627\u06AF\u0631 \u0628\u0631\u0627\u06CC \u0627\u0648\u0644\u06CC\u0646 \u0628\u0627\u0631 \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0628\u0627\u0632\u06CC \u0645\u06CC \u06A9\u0646\u06CC\u062F\u060C \u06CC\u06A9 \u0628\u0633\u062A\u0647 \u062E\u0648\u0634 \u0622\u0645\u062F\u06AF\u0648\u06CC\u06CC \u062F\u0631 \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u067E\u06CC\u062F\u0627 \u062E\u0648\u0627\u0647\u06CC\u062F \u06A9\u0631\u062F. \u0627\u06CC\u0646 \u062C\u0627\u06CC\u0632\u0647 \u0627\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0633\u0641\u0631 \u0634\u0645\u0627 \u0631\u0627 \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0622\u063A\u0627\u0632 \u0645\u06CC \u06A9\u0646\u062F \u0648 \u0628\u0647 \u0634\u0645\u0627 \u06A9\u0645\u06A9 \u0645\u06CC \u06A9\u0646\u062F \u062A\u0627 \u062C\u06A9\u067E\u0627\u062A \u0628\u0632\u0631\u06AF\u06CC \u0631\u0627 \u0628\u062F\u0633\u062A \u0622\u0648\u0631\u06CC\u062F.</p>
  <p>\u0627\u06CC\u0646 \u0641\u0642\u0637 \u067E\u0627\u062F\u0627\u0634 \u062E\u0648\u0634 \u0622\u0645\u062F\u06AF\u0648\u06CC\u06CC \u0646\u06CC\u0633\u062A \u06A9\u0647 \u062F\u0631 \u062F\u0633\u062A\u0631\u0633 \u0627\u0633\u062A. \u067E\u0633 \u0627\u0632 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u067E\u0627\u062F\u0627\u0634 \u062E\u0648\u0634 \u0622\u0645\u062F \u06AF\u0648\u06CC\u06CC\u060C \u0628\u0627\u06CC\u062F \u0686\u0634\u0645 \u062E\u0648\u062F \u0631\u0627 \u0628\u0631\u0627\u06CC \u062F\u0631\u06CC\u0627\u0641\u062A \u067E\u0627\u062F\u0627\u0634 \u0648\u0627\u0631\u06CC\u0632\u06CC \u062F\u0648\u0631 \u0646\u06AF\u0647 \u062F\u0627\u0631\u06CC\u062F. \u0627\u06CC\u0646 \u067E\u0627\u062F\u0627\u0634\u06CC \u0627\u0633\u062A \u06A9\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u06AF\u0627\u0647\u06CC \u0627\u0648\u0642\u0627\u062A \u0628\u0647 \u06CC\u06A9 \u0633\u067E\u0631\u062F\u0647 \u062A\u0635\u0627\u062F\u0641\u06CC \u06A9\u0647 \u062F\u0631 \u0637\u0648\u0644 \u0628\u0627\u0632\u06CC \u062E\u0648\u062F \u062A\u0639\u06CC\u06CC\u0646 \u0645\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0645\u06CC \u062F\u0647\u0646\u062F. \u0648 \u0627\u06AF\u0631 \u062E\u0648\u0634 \u0634\u0627\u0646\u0633 \u0628\u0627\u0634\u06CC\u062F\u060C \u062C\u06A9\u067E\u0627\u062A \u0647\u0627\u06CC \u0628\u0632\u0631\u06AF \u06CC\u0627 \u06A9\u0648\u0686\u06A9\u06CC \u0631\u0627 \u0628\u0627 \u062E\u0648\u062F \u0628\u0647 \u0647\u0645\u0631\u0627\u0647 \u062E\u0648\u0627\u0647\u062F \u062F\u0627\u0634\u062A.</p>
  <p>\u062F\u0631\u0633\u062A \u0645\u0627\u0646\u0646\u062F \u0632\u0645\u0627\u0646\u06CC \u06A9\u0647 \u06CC\u06A9 \u0633\u067E\u0631\u062F\u0647 \u0627\u0633\u062A\u0627\u0646\u062F\u0627\u0631\u062F \u062A\u0646\u0638\u06CC\u0645 \u0645\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0648\u0642\u062A\u06CC \u06CC\u06A9 \u0633\u067E\u0631\u062F\u0647 \u0631\u0645\u0632\u0646\u06AF\u0627\u0631\u06CC \u0645\u06CC \u06AF\u0630\u0627\u0631\u06CC\u062F\u060C \u067E\u0627\u062F\u0627\u0634 \u062E\u0648\u062F \u0631\u0627 \u062F\u0631 \u0635\u0646\u062F\u0648\u0642 \u062F\u0627\u0631 \u062F\u0631\u06CC\u0627\u0641\u062A \u0645\u06CC \u06A9\u0646\u06CC\u062F. \u0648 \u0628\u0647 \u06CC\u0627\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u06CC\u062F \u06A9\u0647 \u0647\u06CC\u0686 \u06A9\u0633 \u0646\u0645\u06CC \u062A\u0648\u0627\u0646\u062F \u0634\u0645\u0627 \u0631\u0627 \u0645\u062C\u0628\u0648\u0631 \u0628\u0647 \u06AF\u0631\u0641\u062A\u0646 \u0622\u0646 \u067E\u0627\u062F\u0627\u0634 \u06A9\u0646\u062F. \u0627\u0646\u062A\u062E\u0627\u0628 \u0628\u0627\u0634\u0645\u0627\u0633\u062A. \u0627\u06CC\u0646 \u0627\u0646\u062A\u062E\u0627\u0628\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0628\u0627\u06CC\u062F \u067E\u0633 \u0627\u0632 \u0628\u0631\u0631\u0633\u06CC \u062A\u0645\u0627\u0645 \u0634\u0631\u0627\u06CC\u0637 \u0648 \u0636\u0648\u0627\u0628\u0637 \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u062C\u0627\u06CC\u0632\u0647 \u0627\u0646\u062C\u0627\u0645 \u062F\u0647\u06CC\u062F. \u0628\u0647 \u06CC\u0627\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u06CC\u062F\u060C \u0642\u0628\u0644 \u0627\u0632 \u0627\u06CC\u0646\u06A9\u0647 \u0628\u062A\u0648\u0627\u0646\u06CC\u062F \u0647\u0631 \u06CC\u06A9 \u0627\u0632 \u0628\u0631\u062F \u0647\u0627\u06CC\u06CC \u0631\u0627 \u06A9\u0647 \u0628\u0647 \u0627\u0646\u062F\u0627\u0632\u0647 \u06A9\u0627\u0641\u06CC \u062F\u0631 \u0622\u0646 \u062E\u0648\u0634 \u0634\u0627\u0646\u0633 \u0628\u0648\u062F\u06CC\u062F \u0628\u0631\u062F\u0627\u0634\u062A \u06A9\u0646\u06CC\u062F\u060C \u0628\u0627\u06CC\u062F \u0634\u0631\u0627\u06CC\u0637 \u0634\u0631\u0637 \u0628\u0646\u062F\u06CC \u0631\u0627 \u0627\u0646\u062C\u0627\u0645 \u062F\u0647\u06CC\u062F. \u0647\u0645\u0686\u0646\u06CC\u0646\u060C \u0628\u0647 \u06CC\u0627\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u06CC\u062F \u06A9\u0647 \u062D\u062A\u06CC \u0627\u06AF\u0631 \u0634\u0627\u0646\u0633 \u0628\u0631\u0646\u062F\u0647 \u0634\u062F\u0646 \u067E\u0648\u0644 \u0632\u06CC\u0627\u062F\u06CC \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F\u060C \u0628\u0627\u06CC\u062F \u0628\u0647 \u062E\u0627\u0637\u0631 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u06CC\u062F \u06A9\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0641\u0642\u0637 \u0628\u0631\u0627\u06CC \u0633\u0631\u06AF\u0631\u0645\u06CC \u0647\u0633\u062A\u0646\u062F.</p>
  
  <h2>\u0646\u062D\u0648\u0647 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0645\u0646\u0627\u0633\u0628</h2>
  <p>\u0647\u0645\u0647 \u0645\u0627 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u0645 \u0641\u0648\u0631\u0627 \u0628\u0647\u062A\u0631\u06CC\u0646 \u06AF\u0632\u06CC\u0646\u0647 \u0631\u0627 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u0645\u060C \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u0645 \u062F\u0631 \u0627\u0648\u0644\u06CC\u0646 \u0686\u0631\u062E\u0634 \u0628\u0647 \u062C\u06A9\u067E\u0627\u062A \u0628\u0631\u0633\u06CC\u0645\u060C \u0647\u0645\u0647 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u0645 \u0647\u0645\u0647 \u0622\u0646 \u0631\u0627 \u0628\u0647 \u062F\u0633\u062A \u0622\u0648\u0631\u06CC\u0645\u060C \u0648 \u0628\u0644\u0627\u0641\u0627\u0635\u0644\u0647 \u0622\u0646 \u0631\u0627 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u0645. \u0645\u062A\u0623\u0633\u0641\u0627\u0646\u0647 \u0627\u06CC\u0646 \u0648\u0627\u0642\u0639\u06CC\u062A \u0646\u06CC\u0633\u062A. \u0645\u0627 \u0645\u06CC \u0622\u0645\u0648\u0632\u06CC\u0645.</p>
  <p>\u0647\u06CC\u0686 \u0646\u0642\u0634\u0647 \u0631\u0627\u0647 \u0645\u062E\u0641\u06CC \u0628\u0631\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u0647\u0627\u06CC \u0647\u0646\u06AF\u0641\u062A \u0648 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0639\u0627\u0644\u06CC \u062F\u0631 \u0627\u0648\u0644\u06CC\u0646 \u0686\u0631\u062E\u0634 \u0648\u062C\u0648\u062F \u0646\u062F\u0627\u0631\u062F\u060C \u062D\u062A\u06CC \u0648\u0642\u062A\u06CC \u0635\u062D\u0628\u062A \u0627\u0632 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0645\u06CC \u0634\u0648\u062F - \u0627\u0645\u0627 \u062F\u0631 \u0627\u06CC\u0646\u062C\u0627 \u0686\u0646\u062F \u0646\u06A9\u062A\u0647 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F:</p>
  <ul>
    <li>\u0628\u0627\u06CC\u062F \u0628\u0628\u06CC\u0646\u06CC\u062F \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0686\u0647 \u0646\u0648\u0639 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC\u06CC \u0631\u0627 \u0627\u0631\u0627\u0626\u0647 \u0645\u06CC\u200C\u062F\u0647\u062F\u060C \u0634\u0627\u06CC\u062F \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u0634\u0645\u0627 \u062F\u0648\u0633\u062A \u062F\u0627\u0631\u06CC\u062F \u0627\u0645\u062A\u062D\u0627\u0646 \u06A9\u0646\u06CC\u062F \u0646\u062F\u0627\u0631\u0646\u062F.</li>
    <li>\u0641\u0631\u0636 \u06A9\u0646\u06CC\u062F \u0634\u0645\u0627 \u06CC\u06A9 \u0646\u0648\u0639 \u0627\u0631\u0632 \u0631\u0645\u0632\u0646\u06AF\u0627\u0631\u06CC \u0634\u062F\u0647 \u062F\u0627\u0631\u06CC\u062F \u0648 \u0646\u0645\u06CC \u062E\u0648\u0627\u0647\u06CC\u062F \u0627\u0631\u0632 \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644\u06CC \u0645\u062A\u0641\u0627\u0648\u062A \u0627\u0632 \u0622\u0646\u0686\u0647 \u0645\u06CC \u0634\u0646\u0627\u0633\u06CC\u062F \u0627\u0645\u062A\u062D\u0627\u0646 \u06A9\u0646\u06CC\u062F. \u062F\u0631 \u0627\u06CC\u0646 \u0635\u0648\u0631\u062A\u060C \u0628\u0627\u06CC\u062F \u0631\u0648\u0634\u200C\u0647\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u0631\u0627 \u0628\u0631\u0631\u0633\u06CC \u06A9\u0646\u06CC\u062F \u062A\u0627 \u0645\u0637\u0645\u0626\u0646 \u0634\u0648\u06CC\u062F \u06A9\u0647 \u0622\u06CC\u0627 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0622\u0646 \u0646\u0648\u0639 \u0631\u0627 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u0631\u0648\u0634 \u067E\u0631\u062F\u0627\u062E\u062A \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u062E\u0648\u062F \u0645\u06CC\u200C\u067E\u0630\u06CC\u0631\u0646\u062F.</li>
    <li>\u067E\u0627\u062F\u0627\u0634 - \u0645\u06CC\u200C\u062F\u0627\u0646\u06CC\u0645 \u06A9\u0647 \u0642\u0628\u0644\u0627\u064B \u062F\u0631 \u0645\u0648\u0631\u062F \u067E\u0627\u062F\u0627\u0634 \u0645\u0647\u0645 \u0635\u062D\u0628\u062A \u06A9\u0631\u062F\u0647 \u0627\u06CC\u0645\u060C \u0627\u0645\u0627 \u0622\u0646 \u0631\u0627 \u062A\u06A9\u0631\u0627\u0631 \u0645\u06CC \u06A9\u0646\u06CC\u0645. \u0645\u0627 \u0645\u06CC\u200C\u062F\u0627\u0646\u06CC\u0645 \u06A9\u0647 \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u0641\u0642\u0637 \u0628\u0647 \u0646\u0648\u0639 \u067E\u0627\u062F\u0627\u0634\u06CC \u06A9\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0628\u0647 \u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u062C\u062F\u06CC\u062F \u0648 \u0642\u062F\u06CC\u0645\u06CC \u062E\u0648\u062F \u0627\u0631\u0627\u0626\u0647 \u0645\u06CC \u062F\u0647\u062F \u062A\u0648\u062C\u0647 \u062F\u0627\u0631\u0646\u062F.</li>
    <li>\u0645\u0637\u0645\u0626\u0646 \u0634\u0648\u06CC\u062F \u06A9\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F - \u0627\u06A9\u062B\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0641\u0647\u0631\u0633\u062A\u06CC \u0627\u0632 \u06A9\u0634\u0648\u0631\u0647\u0627\u06CC \u0645\u062D\u062F\u0648\u062F \u062F\u0627\u0631\u0646\u062F \u06A9\u0647 \u0646\u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u0646\u062F \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u062E\u0648\u062F \u0628\u0627\u0632\u06CC \u06A9\u0646\u0646\u062F. \u0645\u0637\u0645\u0626\u0646 \u0634\u0648\u06CC\u062F \u06A9\u0647 \u06A9\u0634\u0648\u0631 \u0634\u0645\u0627 \u062F\u0631 \u0644\u06CC\u0633\u062A \u0645\u062D\u062F\u0648\u062F \u0646\u06CC\u0633\u062A.</li>
  </ul>
  
  <h2>\u0622\u06CC\u0627 \u0648\u0627\u0631\u06CC\u0632 \u06CC\u0627 \u0628\u0631\u062F\u0627\u0634\u062A \u0645\u0634\u06A9\u0644 \u0627\u0633\u062A\u061F</h2>
  <p>\u062F\u0631\u06A9 \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u0631\u0648\u0634\u200C\u0647\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u062F\u0634\u0648\u0627\u0631 \u0627\u0633\u062A\u060C \u0648 \u0646\u06A9\u062A\u0647 \u0641\u0631\u0648\u0634 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0642\u0631\u0627\u0631 \u0627\u0633\u062A \u0647\u0645\u0647 \u0686\u06CC\u0632 \u0647\u0646\u06AF\u0627\u0645 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0622\u0646 \u062F\u0631 \u062F\u0633\u062A\u0631\u0633\u200C\u062A\u0631 \u0628\u0627\u0634\u062F \u2013 \u0622\u06CC\u0627 \u0622\u0633\u0627\u0646\u200C\u062A\u0631 \u0646\u06CC\u0633\u062A\u061F</p>
  <p>\u0628\u0644\u0647\u060C \u062F\u0632\u062F\u06CC\u062F\u0646 \u0622\u0628 \u0646\u0628\u0627\u062A \u0627\u0632 \u06CC\u06A9 \u0628\u0686\u0647 \u0622\u0633\u0627\u0646 \u0627\u0633\u062A. \u0641\u0642\u0637 \u0686\u0646\u062F \u0645\u0631\u062D\u0644\u0647 \u0628\u0631\u0627\u06CC \u0648\u0627\u0631\u06CC\u0632 \u0648\u062C\u0647 \u0648 \u0641\u0642\u0637 \u0686\u0646\u062F \u0645\u0631\u062D\u0644\u0647 \u0628\u0631\u0627\u06CC \u0628\u0631\u062F\u0627\u0634\u062A \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F. \u0648 \u0627\u0644\u0628\u062A\u0647\u060C \u0645\u0627 \u0627\u06CC\u0646\u062C\u0627 \u0647\u0633\u062A\u06CC\u0645 \u062A\u0627 \u0628\u0647 \u0634\u0645\u0627 \u0628\u06AF\u0648\u06CC\u06CC\u0645 \u0686\u06AF\u0648\u0646\u0647 \u0627\u06CC\u0646 \u06A9\u0627\u0631 \u0631\u0627 \u0627\u0646\u062C\u0627\u0645 \u062F\u0647\u06CC\u062F:</p>
  <p>\u0628\u0647 \u0627\u06CC\u0646 \u0635\u0648\u0631\u062A \u0627\u0633\u062A \u06A9\u0647 \u0628\u0627 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u0627\u0632 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u06CC\u0627 \u0631\u0645\u0632\u0627\u0631\u0632 \u062F\u06CC\u06AF\u0631\u06CC \u0633\u067E\u0631\u062F\u0647 \u06AF\u0630\u0627\u0631\u06CC \u0645\u06CC \u06A9\u0646\u06CC\u062F:</p>
  <ul>
    <li>\u0627\u0628\u062A\u062F\u0627\u060C \u0634\u0645\u0627 \u0628\u0627\u06CC\u062F \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0645\u0648\u0631\u062F \u0639\u0644\u0627\u0642\u0647 \u062E\u0648\u062F \u0631\u0627 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u062F \u06A9\u0647 \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0631\u0627 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u06AF\u0632\u06CC\u0646\u0647 \u067E\u0631\u062F\u0627\u062E\u062A \u0645\u06CC \u067E\u0630\u06CC\u0631\u062F \u0648 \u0628\u0647 \u0635\u0646\u062F\u0648\u0642\u062F\u0627\u0631 \u0631\u0627\u0647 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u062F.</li>
    <li>\u0627\u06AF\u0631 \u0645\u06CC \u062E\u0648\u0627\u0647\u06CC\u062F \u0627\u0632 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u06CC\u0627 \u0646\u0648\u0639 \u062F\u06CC\u06AF\u0631\u06CC \u0627\u0632 \u0631\u0645\u0632\u0646\u06AF\u0627\u0631\u06CC \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F\u060C \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F.</li>
    <li>\u0648 \u0633\u067E\u0633 \u062A\u0646\u0647\u0627 \u0686\u06CC\u0632\u06CC \u06A9\u0647 \u0628\u0627\u0642\u06CC \u0645\u06CC \u0645\u0627\u0646\u062F \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0645\u0642\u062F\u0627\u0631\u06CC \u0631\u0627 \u06A9\u0647 \u0645\u06CC \u062E\u0648\u0627\u0647\u06CC\u062F \u0648\u0627\u0631\u06CC\u0632 \u06A9\u0646\u06CC\u062F \u062A\u0627\u06CC\u067E \u06A9\u0646\u06CC\u062F \u0648 \u0631\u0648\u06CC enter \u06A9\u0644\u06CC\u06A9 \u06A9\u0646\u06CC\u062F. \u0648 \u062F\u0631 \u0639\u0631\u0636 \u0686\u0646\u062F \u0644\u062D\u0638\u0647\u060C \u0645\u0648\u062C\u0648\u062F\u06CC \u0628\u0627\u06CC\u062F \u0631\u0648\u06CC \u062D\u0633\u0627\u0628 \u0628\u0627\u0632\u06CC\u06A9\u0646 \u0634\u0645\u0627 \u0628\u0627\u0634\u062F.</li>
  </ul>
  <p>\u0632\u0645\u0627\u0646\u06CC \u06A9\u0647 \u0628\u0647 \u0627\u0646\u062F\u0627\u0632\u0647 \u06A9\u0627\u0641\u06CC \u062E\u0648\u0634 \u0634\u0627\u0646\u0633 \u0628\u0627\u0634\u06CC\u062F \u06A9\u0647 \u0628\u0631\u0646\u062F\u0647 \u0634\u0648\u06CC\u062F\u060C \u0686\u06AF\u0648\u0646\u0647 \u0628\u0631\u062F\u0627\u0634\u062A \u0645\u06CC \u06A9\u0646\u06CC\u062F:</p>
  <ul>
    <li>\u0627\u0648\u0644\u06CC\u0646 \u06A9\u0627\u0631\u06CC \u06A9\u0647 \u0628\u0627\u06CC\u062F \u0627\u0646\u062C\u0627\u0645 \u062F\u0647\u06CC\u062F \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0628\u0647 \u0635\u0646\u062F\u0648\u0642\u062F\u0627\u0631 \u0628\u0631\u0648\u06CC\u062F \u0648 \u0631\u0648\u0634 \u0628\u0631\u062F\u0627\u0634\u062A\u06CC \u0631\u0627 \u06A9\u0647 \u062A\u0631\u062C\u06CC\u062D \u0645\u06CC \u062F\u0647\u06CC\u062F \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u06CC\u062F \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F</li>
    <li>\u0645\u0628\u0644\u063A\u06CC \u0631\u0627 \u06A9\u0647 \u0645\u06CC \u062E\u0648\u0627\u0647\u06CC\u062F \u0628\u0631\u062F\u0627\u0634\u062A \u06A9\u0646\u06CC\u062F \u067E\u0631 \u06A9\u0646\u06CC\u062F \u0648 \u0633\u067E\u0633 \u062A\u0627\u06CC\u06CC\u062F \u0631\u0627 \u0641\u0634\u0627\u0631 \u062F\u0647\u06CC\u062F</li>
  </ul>
  <p>\u0647\u0645\u0627\u0646\u0637\u0648\u0631 \u06A9\u0647 \u0645\u06CC \u0628\u06CC\u0646\u06CC\u062F\u060C \u0627\u06CC\u0646 \u0628\u0633\u06CC\u0627\u0631 \u0633\u0627\u062F\u0647\u200C\u062A\u0631 \u0627\u0632 \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u06AF\u0632\u06CC\u0646\u0647 \u0647\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u062F\u06CC\u06AF\u0631\u06CC \u0627\u0633\u062A \u06A9\u0647 \u062F\u0631 \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0622\u0646\u0644\u0627\u06CC\u0646 \u067E\u06CC\u062F\u0627 \u0645\u06CC \u06A9\u0646\u06CC\u062F - \u0627\u0645\u0627 \u0647\u0645\u0627\u0646\u0637\u0648\u0631 \u06A9\u0647 \u0647\u0645\u0647 \u0645\u0627 \u0645\u06CC\u200C\u062F\u0627\u0646\u06CC\u0645\u060C \u0627\u06CC\u0646 \u0686\u06CC\u0632\u06CC \u0646\u06CC\u0633\u062A \u06A9\u0647 \u0647\u0645\u0647 \u062C\u0627 \u0645\u06CC \u0628\u06CC\u0646\u06CC\u0645.</p>

  <h2>\u0686\u0647 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC\u06CC \u0631\u0627 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u062F\u0631 \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u06A9\u0631\u06CC\u067E\u062A\u0648 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u062F\u061F</h2>
  <p>\u0686\u06CC\u0632\u06CC \u06A9\u0647 \u0628\u0647\u062A\u0631\u06CC\u0646 \u062A\u062C\u0631\u0628\u0647 \u06A9\u0627\u0631\u0628\u0631\u06CC \u0631\u0627 \u0628\u0631\u0627\u06CC \u06CC\u06A9 \u0633\u0627\u06CC\u062A \u0642\u0645\u0627\u0631 \u0622\u0646\u0644\u0627\u06CC\u0646 \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC \u06A9\u0646\u062F\u060C \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u062F. \u06CC\u06A9 \u0628\u0627\u0632\u06CC\u06A9\u0646 \u0628\u0627\u06CC\u062F \u0628\u062A\u0648\u0627\u0646\u062F \u0686\u0646\u062F \u0645\u0648\u0631\u062F \u0631\u0627 \u0628\u0631\u0627\u06CC \u0627\u0646\u062A\u062E\u0627\u0628 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u062F \u0648 \u0628\u0627\u06CC\u062F \u0646\u0648\u0639\u06CC \u062A\u0639\u0627\u062F\u0644 \u0628\u0631\u0627\u06CC \u0628\u0627\u0632 \u0646\u06AF\u0647 \u062F\u0627\u0634\u062A\u0646 \u0628\u0627\u0632\u0627\u0631 \u0628\u0631\u0627\u06CC \u0628\u06CC\u0634 \u0627\u0632 \u06CC\u06A9 \u0646\u0648\u0639 \u0628\u0627\u0632\u06CC\u06A9\u0646 \u0648\u062C\u0648\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u062F.</p>
  <p>\u0628\u062E\u0634 \u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u0645\u062D\u0628\u0648\u0628\u06CC\u062A \u0645\u0637\u0644\u0642 \u062F\u0631 \u0628\u06CC\u0646 \u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u0645\u0648\u062C\u0648\u062F \u062F\u0631 \u0628\u0627\u0632\u0627\u0631 \u0647\u0633\u062A\u0646\u062F\u060C \u0648 \u0627\u062C\u0627\u0632\u0647 \u062F\u0647\u06CC\u062F \u06A9\u0645\u06CC \u0627\u0632 \u0627\u0646\u062A\u0638\u0627\u0631\u0627\u062A \u0634\u0645\u0627 \u0627\u0632 \u06CC\u06A9 \u062F\u0633\u062A\u06AF\u0627\u0647 \u0627\u0633\u0644\u0627\u062A \u0622\u0646\u0644\u0627\u06CC\u0646 \u062F\u0631 \u06CC\u06A9 \u0633\u0627\u06CC\u062A \u0642\u0645\u0627\u0631 \u0627\u0631\u0632 \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644 \u0628\u0647 \u0634\u0645\u0627 \u0628\u06AF\u0648\u06CC\u06CC\u0645.</p>
  <p>\u0647\u0631 \u0628\u0627\u0632\u06CC \u0631\u0648\u06CC \u06CC\u06A9 \u0645\u0627\u0634\u06CC\u0646 \u0627\u0633\u0644\u0627\u062A \u06A9\u0627\u0645\u0644\u0627 \u062A\u0635\u0627\u062F\u0641\u06CC \u062E\u0648\u0627\u0647\u062F \u0628\u0648\u062F\u060C \u062F\u0631\u0633\u062A \u0645\u0627\u0646\u0646\u062F \u067E\u0631\u062A\u0627\u0628 \u0633\u06A9\u0647. \u0628\u0631\u0646\u0627\u0645\u0647 \u0631\u0627\u06CC\u0627\u0646\u0647 \u0627\u06CC \u06A9\u0647 \u0628\u0627\u0632\u06CC \u0631\u0627 \u06A9\u0646\u062A\u0631\u0644 \u0645\u06CC \u06A9\u0646\u062F \u06CC\u06A9 \u0646\u0645\u0627\u062F \u062A\u0635\u0627\u062F\u0641\u06CC \u0631\u0627 \u062F\u0631 \u0631\u062F\u06CC\u0641 \u0627\u0648\u0644 \u0648 \u0633\u067E\u0633 \u0631\u062F\u06CC\u0641 \u062F\u0648\u0645 \u0627\u0646\u062A\u062E\u0627\u0628 \u0645\u06CC \u06A9\u0646\u062F. \u0628\u0627\u0632\u067E\u0631\u062F\u0627\u062E\u062A \u062F\u0631\u0635\u062F \u067E\u0648\u0644\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0628\u0647 \u0637\u0648\u0631 \u0645\u062A\u0648\u0633\u0637 \u200B\u200B\u0628\u0647 \u0628\u0627\u0632\u06CC\u06A9\u0646 \u0628\u0627\u0632\u067E\u0631\u062F\u0627\u062E\u062A \u0645\u06CC \u0634\u0648\u062F. \u0647\u0631 \u0686\u0631\u062E\u0634 \u062F\u0631 \u0628\u0627\u0632\u06CC \u0634\u0627\u0646\u0633 \u0628\u0631\u062F \u06CC\u0627 \u0628\u0627\u062E\u062A\u06CC \u0645\u0634\u0627\u0628\u0647 \u0628\u0627\u0632\u06CC \u0642\u0628\u0644\u06CC \u062F\u0627\u0631\u062F. \u0647\u06CC\u0686 \u0686\u06CC\u0632\u06CC \u0628\u0631\u0627\u06CC \u06AF\u0641\u062A\u0646 \u0646\u062F\u0627\u0631\u062F \u06A9\u0647 \u0627\u0632 \u0622\u062E\u0631\u06CC\u0646 \u062C\u06A9\u067E\u0627\u062A \u067E\u0631\u062F\u0627\u062E\u062A\u06CC \u0686\u0647 \u0645\u062F\u062A \u0645\u06CC \u06AF\u0630\u0631\u062F \u06CC\u0627 \u0627\u06CC\u0646\u06A9\u0647 \u062F\u0633\u062A\u06AF\u0627\u0647 \u0627\u0633\u0644\u0627\u062A '\u06AF\u0631\u0645' \u0627\u0633\u062A \u06CC\u0627 '\u0633\u0631\u062F'</p>
  <p>\u062F\u0631 \u062F\u0647\u0647 80\u060C \u062F\u0633\u062A\u06AF\u0627\u0647 \u0647\u0627\u06CC \u0627\u0633\u0644\u0627\u062A \u0628\u0633\u06CC\u0627\u0631 \u0645\u062D\u0628\u0648\u0628 \u0634\u062F\u0646\u062F \u0648 \u062D\u062A\u06CC \u0627\u0632 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC \u0631\u0648\u0645\u06CC\u0632\u06CC \u0645\u0627\u0646\u0646\u062F \u06A9\u0631\u067E\u0633 \u0648 \u0628\u0644\u06A9 \u062C\u06A9 \u0646\u06CC\u0632 \u067E\u06CC\u0634\u06CC \u06AF\u0631\u0641\u062A\u0646\u062F. \u062F\u0633\u062A\u06AF\u0627\u0647 \u0647\u0627\u06CC \u0627\u0633\u0644\u0627\u062A \u0648 \u067E\u0648\u06A9\u0631 \u0648\u06CC\u062F\u06CC\u0648\u06CC\u06CC \u0627\u06A9\u0646\u0648\u0646 \u0628\u06CC\u0634 \u0627\u0632 70 \u062F\u0631\u0635\u062F \u0627\u0632 \u0633\u0648\u062F \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0631\u0627 \u062A\u0634\u06A9\u06CC\u0644 \u0645\u06CC \u062F\u0647\u0646\u062F. \u0627\u06A9\u0646\u0648\u0646 \u06A9\u0647 \u0622\u0646\u0644\u0627\u06CC\u0646 \u0634\u062F\u0647 \u0627\u06CC\u0645\u060C \u0647\u0645\u0686\u0646\u0627\u0646 \u0627\u0632 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0648 \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0648 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u0631\u0648\u0634 \u0647\u0627\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0631\u0627 \u0646\u0645\u06CC \u067E\u0630\u06CC\u0631\u0646\u062F\u060C \u0633\u0648\u062F \u0645\u06CC \u0628\u0631\u062F. \u0627\u06CC\u0646 \u0628\u0647 \u06CC\u06A9 \u062F\u0644\u06CC\u0644 \u0633\u0627\u062F\u0647 \u0627\u0633\u062A: \u062C\u06A9\u067E\u0627\u062A \u0647\u0627\u06CC \u0628\u0632\u0631\u06AF. \u0632\u0645\u0627\u0646\u06CC \u06A9\u0647 \u0645\u0627\u0634\u06CC\u0646\u200C\u0647\u0627\u06CC \u0628\u0627\u0632\u06CC \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644\u06CC \u0634\u062F\u0646\u062F\u060C \u0627\u0645\u06A9\u0627\u0646 \u0628\u0631\u0646\u062F\u0647 \u0634\u062F\u0646 \u062C\u06A9\u200C\u067E\u0627\u062A \u06A9\u0645\u062A\u0631 \u0634\u062F\u060C \u06A9\u0647 \u0647\u0645\u0686\u0646\u06CC\u0646 \u0628\u0647 \u0627\u06CC\u0646 \u0645\u0639\u0646\u06CC \u0628\u0648\u062F \u06A9\u0647 \u062C\u06A9\u200C\u067E\u0627\u062A \u062F\u0631 \u0645\u0627\u0634\u06CC\u0646\u200C\u0647\u0627\u06CC \u0627\u0633\u0644\u0627\u062A \u0622\u0646\u0644\u0627\u06CC\u0646 \u0632\u0645\u0627\u0646\u06CC \u06A9\u0647 \u0628\u0631\u0627\u06CC \u0627\u0648\u0644\u06CC\u0646 \u0628\u0627\u0631 \u0622\u0646 \u0631\u0627 \u0628\u0631\u062F\u06CC\u062F \u0628\u0632\u0631\u06AF\u200C\u062A\u0631 \u0634\u062F. \u0648 \u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u062C\u06A9\u067E\u0627\u062A \u0647\u0627\u06CC \u0628\u0632\u0631\u06AF \u0631\u0627 \u062F\u0648\u0633\u062A \u062F\u0627\u0631\u0646\u062F! \u0627\u06AF\u0631 \u0628\u0627 5 \u062F\u0644\u0627\u0631 \u0631\u0648\u06CC \u0645\u06CC\u0632 \u0628\u0644\u06A9 \u062C\u06A9 \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u062D\u062F\u0627\u06A9\u062B\u0631 7.5 \u062F\u0644\u0627\u0631 \u0628\u0631\u0646\u062F\u0647 \u0634\u0648\u06CC\u062F\u060C \u0627\u0645\u0627 \u0627\u06AF\u0631 \u0628\u0627 3 \u062F\u0644\u0627\u0631 \u0631\u0648\u06CC \u06CC\u06A9 \u062F\u0633\u062A\u06AF\u0627\u0647 \u0627\u0633\u0644\u0627\u062A \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0686\u0646\u062F\u06CC\u0646 \u0647\u0632\u0627\u0631 \u06CC\u0627 \u0645\u06CC\u0644\u06CC\u0648\u0646 \u062F\u0644\u0627\u0631 \u062F\u0631 \u06CC\u06A9 \u062D\u0631\u06A9\u062A \u0628\u0631\u0646\u062F\u0647 \u0634\u0648\u06CC\u062F\u060C \u0627\u0645\u0627 \u0627\u06CC\u0646 \u0641\u0642\u0637 \u062F\u0631 \u0635\u0648\u0631\u062A\u06CC \u0627\u0633\u062A \u06A9\u0647 \u062E\u0648\u0634 \u0634\u0627\u0646\u0633 \u0628\u0627\u0634\u06CC\u062F. \u0647\u0645\u0627\u0646\u0637\u0648\u0631 \u06A9\u0647 \u0642\u0628\u0644\u0627\u064B \u06AF\u0641\u062A\u06CC\u0645\u060C \u0634\u0645\u0627 \u0628\u0627\u06CC\u062F \u0647\u0645\u06CC\u0634\u0647 \u0628\u0647 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u0633\u0631\u06AF\u0631\u0645\u06CC \u0646\u06AF\u0627\u0647 \u06A9\u0646\u06CC\u062F \u0648 \u0646\u0647 \u06CC\u06A9 \u067E\u0631\u062F\u0627\u062E\u062A \u0633\u0631\u06CC\u0639.</p>
  <p>\u0627\u0645\u0627 \u0639\u0644\u06CC\u0631\u063A\u0645 \u0645\u062D\u0628\u0648\u0628\u06CC\u062A \u0622\u0646\u0647\u0627\u060C \u0633\u0647 \u0645\u0634\u06A9\u0644 \u0639\u0645\u062F\u0647 \u062F\u0631 \u0628\u0627\u0632\u06CC \u06A9\u0631\u062F\u0646 \u0645\u0627\u0634\u06CC\u0646 \u0647\u0627\u06CC \u0627\u0633\u0644\u0627\u062A \u062F\u0631 \u0645\u0642\u0627\u0628\u0644 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC \u0631\u0648\u0645\u06CC\u0632\u06CC \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F. \u0627\u0648\u0644 \u0627\u0632 \u0647\u0645\u0647\u060C \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0647\u0645\u06CC\u0634\u0647 \u062F\u0631 \u0645\u0648\u0631\u062F \u0634\u0627\u0646\u0633\u06CC \u06A9\u0647 \u0628\u0631\u0627\u06CC \u0647\u0631 \u0628\u0627\u0632\u06CC \u0645\u06CC \u06AF\u0630\u0627\u0631\u0646\u062F \u0628\u0627\u0632 \u0646\u06CC\u0633\u062A\u0646\u062F\u060C \u0648 \u0627\u06CC\u0646 \u0628\u062F\u0627\u0646 \u0645\u0639\u0646\u06CC \u0627\u0633\u062A \u06A9\u0647 \u062F\u0627\u0646\u0633\u062A\u0646 \u0627\u062D\u062A\u0645\u0627\u0644 \u0628\u0631\u0646\u062F\u0647 \u0634\u062F\u0646 \u0622\u0646 \u062F\u0634\u0648\u0627\u0631 \u0627\u0633\u062A. \u062F\u0648\u0645\u060C \u0645\u0647\u0645 \u0646\u06CC\u0633\u062A \u06A9\u0647 \u0627\u06CC\u0646 \u0634\u0627\u0646\u0633 \u0647\u0627\u06CC \u0645\u062E\u0641\u06CC \u0686\u0642\u062F\u0631 \u0647\u0633\u062A\u0646\u062F\u060C \u0627\u063A\u0644\u0628 \u0627\u0634\u062A\u0628\u0627\u0647 \u0648 \u0628\u062F\u062A\u0631 \u0627\u0632 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC \u0631\u0648\u0645\u06CC\u0632\u06CC \u0645\u0627\u0646\u0646\u062F \u06A9\u0631\u067E\u0633\u060C \u0628\u0627\u06A9\u0627\u0631\u0627\u062A \u0648 \u0628\u0644\u06A9 \u062C\u06A9 \u0647\u0633\u062A\u0646\u062F. \u0633\u0648\u0645 \u0627\u06CC\u0646\u06A9\u0647 \u062F\u0633\u062A\u06AF\u0627\u0647 \u0647\u0627\u06CC \u0627\u0633\u0644\u0627\u062A \u0628\u0633\u06CC\u0627\u0631 \u0633\u0631\u06CC\u0639\u062A\u0631 \u0627\u0632 \u0633\u0627\u06CC\u0631 \u0628\u0627\u0632\u06CC \u0647\u0627 \u06A9\u0627\u0631 \u0645\u06CC \u06A9\u0646\u0646\u062F \u0648 \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u062F\u0631 \u0645\u062F\u062A \u0632\u0645\u0627\u0646 \u06A9\u0648\u062A\u0627\u0647\u06CC \u067E\u0648\u0644 \u0632\u06CC\u0627\u062F\u06CC \u0627\u0632 \u062F\u0633\u062A \u0628\u062F\u0647\u06CC\u062F.</p>
  <p>\u0628\u0627\u0632\u06CC \u0647\u0627\u06CC \u0631\u0648\u0645\u06CC\u0632\u06CC \u0627\u062A\u0641\u0627\u0642 \u0628\u0632\u0631\u06AF \u0628\u0639\u062F\u06CC \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u0647\u0633\u062A\u0646\u062F\u060C \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0628\u06CC\u0627\u06CC\u06CC\u062F \u062F\u0631 \u0645\u0648\u0631\u062F \u0622\u0646\u0686\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0627\u0632 \u0627\u06CC\u0646 \u0646\u0648\u0639 \u0628\u0627\u0632\u06CC \u0627\u0646\u062A\u0638\u0627\u0631 \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u06CC\u062F \u0635\u062D\u0628\u062A \u06A9\u0646\u06CC\u0645 \u0648 \u0628\u0647 \u0634\u0645\u0627 \u062A\u0627\u0632\u0647 \u06A9\u0627\u0631\u0647\u0627 \u0627\u06CC\u0646 \u0641\u0631\u0635\u062A \u0631\u0627 \u0645\u06CC \u062F\u0647\u06CC\u0645 \u06A9\u0647 \u0642\u0628\u0644 \u0627\u0632 \u062E\u0631\u06CC\u062F \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u0628\u0647 \u0633\u0631\u0639\u062A \u06CC\u0627\u062F \u0628\u06AF\u06CC\u0631\u0646\u062F \u062A\u0627 \u067E\u0648\u0644\u06CC \u0631\u0627 \u06A9\u0647 \u0628\u0647 \u0633\u062E\u062A\u06CC \u0628\u0647 \u062F\u0633\u062A \u0622\u0648\u0631\u062F\u0647\u200C\u0627\u0646\u062F \u0631\u0627 \u062F\u0631 \u0627\u0633\u0644\u0627\u062A\u200C\u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u06CC\u0627 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC \u062F\u06CC\u06AF\u0631 \u0628\u0631\u0627\u06CC \u067E\u0631\u062F\u0627\u062E\u062A \u0633\u0631\u06CC\u0639 \u062E\u0631\u062C \u06A9\u0646\u0646\u062F.</p>
  <p>\u0628\u06CC\u0634\u062A\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC \u0631\u0648\u0645\u06CC\u0632\u06CC \u0631\u0627 \u0627\u0631\u0627\u0626\u0647 \u0645\u06CC\u200C\u062F\u0647\u0646\u062F\u060C \u0648 \u0627\u06AF\u0631 \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648\u06CC\u06CC \u0628\u0627\u0632\u06CC \u0645\u06CC\u200C\u06A9\u0646\u06CC\u062F \u06A9\u0647 \u0622\u0646\u200C\u0647\u0627 \u0631\u0627 \u0646\u062F\u0627\u0631\u062F\u060C \u0628\u0627\u06CC\u062F \u06A9\u0627\u0632\u06CC\u0646\u0648\u06CC \u062F\u06CC\u06AF\u0631\u06CC \u0631\u0627 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u062F \u06A9\u0647 \u0627\u06CC\u0646 \u0628\u0627\u0632\u06CC \u0631\u0627 \u0627\u0631\u0627\u0626\u0647 \u062F\u0647\u062F.</p>
  <p>\u0628\u0631\u0627\u06CC \u0627\u0646\u062C\u0627\u0645 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC \u0631\u0648\u0645\u06CC\u0632\u06CC \u0645\u062C\u0628\u0648\u0631 \u0646\u06CC\u0633\u062A\u06CC\u062F \u0628\u0631\u0627\u06CC \u067E\u0648\u0644 \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F. \u0628\u0633\u06CC\u0627\u0631\u06CC \u0627\u0632 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0628\u0627\u0632\u06CC \u0631\u0627\u06CC\u06AF\u0627\u0646 \u06CC\u0627 \u0628\u0627\u0632\u06CC \u0622\u0632\u0645\u0627\u06CC\u0634\u06CC \u0631\u0627 \u0627\u0631\u0627\u0626\u0647 \u0645\u06CC \u062F\u0647\u0646\u062F\u060C \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0634\u0645\u0627 \u067E\u0648\u0644 \u0648\u0627\u0642\u0639\u06CC \u0631\u0627 \u0648\u0627\u0631\u06CC\u0632 \u0646\u0645\u06CC \u06A9\u0646\u06CC\u062F. \u062F\u0631 \u062F\u0631\u0627\u0632 \u0645\u062F\u062A\u060C \u0627\u06CC\u0646 \u0645\u0645\u06A9\u0646 \u0627\u0633\u062A \u06A9\u0645\u06CC \u062E\u0633\u062A\u0647 \u06A9\u0646\u0646\u062F\u0647 \u0634\u0648\u062F\u060C \u0627\u0645\u0627 \u0641\u0631\u0635\u062A \u0647\u0627\u06CC \u06A9\u0627\u0645\u0644\u06CC \u0628\u0631\u0627\u06CC \u0648\u0627\u0631\u06CC\u0632 \u067E\u0648\u0644 \u0646\u0642\u062F \u062F\u0631 \u062A\u0627\u0631\u06CC\u062E \u0628\u0639\u062F\u06CC \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F.</p>
  <p>\u0627\u06CC\u0646\u06A9\u0647 \u0686\u0642\u062F\u0631 \u062F\u0631 \u06CC\u06A9 \u0628\u0627\u0632\u06CC \u0631\u0648\u0645\u06CC\u0632\u06CC \u0634\u0631\u0637 \u0628\u0646\u062F\u06CC \u0645\u06CC \u06A9\u0646\u06CC\u062F \u0628\u0647 \u062E\u0648\u062F\u062A\u0627\u0646 \u0628\u0633\u062A\u06AF\u06CC \u062F\u0627\u0631\u062F\u060C \u0627\u0645\u0627 \u0627\u063A\u0644\u0628 \u062D\u062F\u0627\u0642\u0644 \u0634\u0631\u0637 \u0628\u0646\u062F\u06CC \u0628\u0631\u0627\u06CC \u0634\u0631\u06A9\u062A \u0627\u0633\u062A. \u0627\u06CC\u0646 \u062F\u0631 \u0633\u0627\u06CC\u062A\u200C\u0647\u0627\u06CC \u0645\u062E\u062A\u0644\u0641 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0645\u062A\u0641\u0627\u0648\u062A \u0627\u0633\u062A\u060C \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0648\u0642\u062A\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648\u06CC\u06CC \u0631\u0627 \u067E\u06CC\u062F\u0627 \u06A9\u0631\u062F\u06CC\u062F \u06A9\u0647 \u062F\u0631 \u0622\u0646 \u0628\u0627\u0632\u06CC \u0645\u06CC\u200C\u06A9\u0646\u06CC\u062F\u060C \u062E\u0648\u062F\u062A\u0627\u0646 \u0622\u0646\u0631\u0627 \u0628\u0631\u0631\u0633\u06CC \u06A9\u0646\u06CC\u062F.</p>
  <p>\u0628\u0644\u06A9 \u062C\u06A9 \u0622\u0646\u0644\u0627\u06CC\u0646 \u06A9\u0647 \u0628\u06CC\u0633\u062A \u0648 \u06CC\u06A9 \u0646\u06CC\u0632 \u0646\u0627\u0645\u06CC\u062F\u0647 \u0645\u06CC \u0634\u0648\u062F\u060C \u06CC\u06A9 \u0628\u0627\u0632\u06CC \u0631\u0648\u0645\u06CC\u0632\u06CC \u0627\u0633\u062A \u06A9\u0647 \u0627\u06A9\u062B\u0631 \u0645\u0631\u062F\u0645 \u0622\u0646 \u0631\u0627 \u0628\u0627 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0645\u0631\u062A\u0628\u0637 \u0645\u06CC\u200C\u062F\u0627\u0646\u0646\u062F. \u0627\u0645\u0631\u0648\u0632\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0644\u06A9 \u062C\u06A9 \u0631\u0627 \u062F\u0631 \u062E\u0627\u0646\u0647 \u062F\u0631 \u0627\u062A\u0627\u0642 \u0646\u0634\u06CC\u0645\u0646 \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0628\u0647 \u0634\u0631\u0637\u06CC \u06A9\u0647 \u0628\u0647 \u0635\u0648\u0631\u062A \u0622\u0646\u0644\u0627\u06CC\u0646 \u0648\u0635\u0644 \u0634\u0648\u06CC\u062F \u0648 \u062F\u0631 \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0633\u067E\u0631\u062F\u0647 \u06AF\u0630\u0627\u0631\u06CC \u06A9\u0646\u06CC\u062F. \u0647\u0645\u0647 \u0627\u0631\u0627\u0626\u0647 \u062F\u0647\u0646\u062F\u06AF\u0627\u0646 \u0627\u0635\u0644\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0628\u0644\u06A9 \u062C\u06A9 \u0631\u0627 \u062F\u0631 \u06A9\u0627\u0631\u0646\u0627\u0645\u0647 \u062E\u0648\u062F \u062F\u0627\u0631\u0646\u062F.</p>
  <p>\u067E\u0648\u06A9\u0631 \u0622\u0646\u0644\u0627\u06CC\u0646 \u06CC\u06A9 \u0628\u0627\u0632\u06CC \u06A9\u0627\u0631\u062A\u06CC \u0647\u06CC\u062C\u0627\u0646 \u0627\u0646\u06AF\u06CC\u0632 \u0627\u0633\u062A \u06A9\u0647 \u0628\u0631\u0627\u06CC \u0627\u06A9\u062B\u0631 \u0627\u0641\u0631\u0627\u062F \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062A. \u062E\u0648\u0628 \u0634\u062F\u0646 \u062F\u0631 \u067E\u0648\u06A9\u0631 \u0632\u0645\u0627\u0646 \u0645\u06CC \u0628\u0631\u062F \u0648 \u0628\u062D\u062B \u0647\u0627\u06CC \u0632\u06CC\u0627\u062F\u06CC \u062F\u0631 \u0645\u0648\u0631\u062F \u0627\u06CC\u0646\u06A9\u0647 \u0622\u06CC\u0627 \u067E\u0648\u06A9\u0631 \u06CC\u06A9 \u0628\u0627\u0632\u06CC \u0645\u0647\u0627\u0631\u062A\u06CC \u0627\u0633\u062A \u0648\u062C\u0648\u062F \u062F\u0627\u0634\u062A\u0647 \u0627\u0633\u062A. \u062F\u0631 \u0627\u06CC\u0646\u062C\u0627\u060C \u0646\u0638\u0631\u0627\u062A \u0645\u062A\u0636\u0627\u062F\u06CC \u0627\u0632 \u0637\u0631\u0641 \u0635\u0646\u0639\u062A \u067E\u0648\u06A9\u0631 \u0648 \u0645\u0642\u0627\u0645\u0627\u062A \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F. \u0635\u0646\u0639\u062A \u067E\u0648\u06A9\u0631 \u0628\u0647 \u0646\u0648\u0628\u0647 \u062E\u0648\u062F \u0645\u0639\u062A\u0642\u062F \u0627\u0633\u062A \u06A9\u0647 \u0627\u06CC\u0646 \u06CC\u06A9 \u0628\u0627\u0632\u06CC \u0645\u0647\u0627\u0631\u062A\u06CC \u0627\u0633\u062A. \u062F\u0631 \u0647\u0645\u0627\u0646 \u0632\u0645\u0627\u0646\u060C \u0645\u0642\u0627\u0645\u0627\u062A \u067E\u0648\u06A9\u0631 \u0631\u0627 \u0628\u0647 \u0639\u0646\u0648\u0627\u0646 \u06CC\u06A9 \u0628\u0627\u0632\u06CC \u062A\u062D\u062A \u0642\u0627\u0646\u0648\u0646 \u0642\u0631\u0639\u0647 \u06A9\u0634\u06CC \u0645\u06CC \u0628\u06CC\u0646\u0646\u062F \u0648 \u0628\u06CC\u0634\u062A\u0631 \u0628\u0647 \u062F\u0646\u0628\u0627\u0644 \u0634\u0627\u0646\u0633 \u0647\u0633\u062A\u0646\u062F \u062A\u0627 \u0645\u0647\u0627\u0631\u062A.</p>
  <p>\u0648\u06CC\u062F\u0626\u0648 \u067E\u0648\u06A9\u0631 \u062F\u0631 \u0627\u0648\u0627\u06CC\u0644 \u062F\u06CC\u062C\u06CC\u062A\u0627\u0644\u06CC \u0634\u062F\u0646 \u0628\u0648\u062F\u060C \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u06CC\u06A9\u06CC \u0627\u0632 \u0627\u0648\u0644\u06CC\u0646 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC\u06CC \u0628\u0648\u062F \u06A9\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u0633\u062A\u06CC\u062F \u0628\u062F\u0648\u0646 \u0646\u06CC\u0627\u0632 \u0628\u0647 \u0646\u06AF\u0647 \u062F\u0627\u0634\u062A\u0646 \u06A9\u0627\u0631\u062A \u062F\u0631 \u062F\u0633\u062A \u062E\u0648\u062F \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F. \u067E\u0648\u06A9\u0631 \u0648\u06CC\u062F\u06CC\u0648\u06CC\u06CC \u062A\u0642\u0631\u06CC\u0628\u0627\u064B \u0647\u0645\u06CC\u0634\u0647 \u0645\u0628\u062A\u0646\u06CC \u0628\u0631 \u067E\u0648\u06A9\u0631 \u0645\u0639\u0645\u0648\u0644\u06CC \u0627\u0633\u062A\u060C \u062C\u0627\u06CC\u06CC \u06A9\u0647 \u0634\u0645\u0627 \u0628\u0627 \u067E\u0646\u062C \u06A9\u0627\u0631\u062A \u0628\u0631\u062A\u0631 \u062F\u0631 \u062F\u0633\u062A \u062E\u0648\u062F \u0628\u0627\u0632\u06CC \u0645\u06CC \u06A9\u0646\u06CC\u062F.</p>
  <p>\u062C\u06A9\u060C \u06CC\u0627 \u0628\u0647\u062A\u0631 \u0627\u0633\u062A \u0628\u06AF\u0648\u06CC\u06CC\u0645 \u06CC\u06A9 \u0634\u06A9\u0644 \u0631\u0627\u06CC\u062C \u0627\u0632 \u067E\u0648\u06A9\u0631 \u0648\u06CC\u062F\u0626\u0648\u06CC\u06CC \u0627\u0633\u062A. \u062F\u0631 \u0627\u06CC\u0646\u062C\u0627 \u0634\u0645\u0627 \u0628\u0647 \u0645\u062D\u0636 \u062F\u0627\u0634\u062A\u0646 \u06CC\u06A9 \u062C\u0641\u062A \u062C\u06A9 \u06CC\u0627 \u0628\u0647\u062A\u0631 \u0628\u0631\u0646\u062F\u0647 \u0645\u06CC \u0634\u0648\u06CC\u062F.</p>
  <p>\u062F\u0631 \u0631\u0648\u0644\u062A\u060C \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u0631\u0648\u06CC \u062A\u0631\u06A9\u06CC\u0628\u200C\u0647\u0627\u060C \u0627\u0639\u062F\u0627\u062F \u062A\u06A9\u06CC\u060C \u0631\u0646\u06AF\u200C\u0647\u0627\u060C \u0631\u062F\u06CC\u0641\u200C\u0647\u0627 \u0648 \u0627\u06CC\u0646\u06A9\u0647 \u062A\u0648\u067E \u0631\u0648\u06CC \u0627\u0639\u062F\u0627\u062F \u0641\u0631\u062F \u06CC\u0627 \u0632\u0648\u062C \u0642\u0631\u0627\u0631 \u0645\u06CC\u200C\u06AF\u06CC\u0631\u062F\u060C \u0634\u0631\u0637 \u0628\u0646\u062F\u06CC \u06A9\u0646\u06CC\u062F. \u0645\u0642\u062F\u0627\u0631 \u067E\u0631\u062F\u0627\u062E\u062A \u0628\u0633\u062A\u0647 \u0628\u0647 \u0686\u06CC\u0632\u06CC \u06A9\u0647 \u0631\u0648\u06CC \u0622\u0646 \u0634\u0631\u0637 \u0628\u0646\u062F\u06CC \u0645\u06CC \u06A9\u0646\u06CC\u062F \u0645\u062A\u0641\u0627\u0648\u062A \u0627\u0633\u062A. \u0628\u0631\u0627\u06CC \u0627\u0639\u062F\u0627\u062F \u0632\u0648\u062C \u0648 \u0627\u0639\u062F\u0627\u062F \u0641\u0631\u062F\u060C \u0645\u0628\u0644\u063A \u067E\u0631\u062F\u0627\u062E\u062A\u06CC 1 \u0628\u0647 1 \u0627\u0633\u062A \u06A9\u0647 \u0628\u0631\u0627\u06CC \u0642\u0631\u0645\u0632 \u06CC\u0627 \u0633\u06CC\u0627\u0647 \u0627\u0639\u0645\u0627\u0644 \u0645\u06CC \u0634\u0648\u062F.</p>
  <p>\u0647\u0645\u0686\u0646\u06CC\u0646 \u0645\u062D\u062F\u0648\u062F\u0647 \u0645\u062A\u0641\u0627\u0648\u062A\u06CC \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F \u06A9\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u062F\u0631 \u0627\u06CC\u0646\u062C\u0627 \u0634\u0631\u0637 \u0628\u0646\u062F\u06CC \u06A9\u0646\u06CC\u062F. \u0628\u0633\u062A\u0647 \u0628\u0647 \u0627\u06CC\u0646\u06A9\u0647 \u06A9\u062F\u0627\u0645 \u0632\u0645\u06CC\u0646\u0647 \u0631\u0627 \u0627\u0646\u062A\u062E\u0627\u0628 \u06A9\u0646\u06CC\u062F\u060C \u067E\u0631\u062F\u0627\u062E\u062A \u0645\u062A\u0641\u0627\u0648\u062A \u0627\u0633\u062A.</p>
  <p>Craps \u06CC\u06A9 \u0628\u0627\u0632\u06CC \u062A\u0627\u0633 \u0627\u0633\u062A \u06A9\u0647 \u062F\u0631 \u0622\u0646 \u0628\u0627\u0632\u06CC\u06A9\u0646 \u0631\u0648\u06CC \u0646\u062A\u06CC\u062C\u0647 \u062F\u0648 \u062A\u0627\u0633 \u0634\u0631\u0637 \u0628\u0646\u062F\u06CC \u0645\u06CC \u06A9\u0646\u062F. \u062E\u06CC\u0644\u06CC \u0633\u0627\u062F\u0647 \u0628\u0647 \u0646\u0638\u0631 \u0645\u06CC \u0631\u0633\u062F \u0627\u0645\u0627 \u0627\u062D\u062A\u0645\u0627\u0644\u0627\u064B \u0628\u0631\u0627\u06CC \u062F\u0631\u06A9 \u0646\u062D\u0648\u0647 \u0627\u062C\u0631\u0627\u06CC \u0628\u0627\u0632\u06CC \u0646\u06CC\u0627\u0632 \u0628\u0647 \u062A\u0648\u0636\u06CC\u062D \u062F\u0627\u0631\u062F. \u0645\u0632\u06CC\u062A \u06A9\u0631\u067E \u0647\u0627 \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0628\u0631\u0627\u06CC \u0628\u0627\u0632\u06CC \u0641\u0642\u0637 \u062A\u0627\u0633 \u0644\u0627\u0632\u0645 \u0627\u0633\u062A\u060C \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u062A\u0627 \u0632\u0645\u0627\u0646\u06CC \u06A9\u0647 \u062F\u0648 \u062A\u0627\u0633 \u062F\u0627\u0631\u06CC\u062F \u0628\u0647 \u0631\u0627\u062D\u062A\u06CC \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u06A9\u0631\u067E \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F.</p>
  <p>\u0627\u06AF\u0631 \u0628\u0647 \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0631\u0641\u062A\u0647 \u0627\u06CC\u062F\u060C \u0645\u06CC\u200C\u062F\u0627\u0646\u06CC\u062F \u06A9\u0647 \u0686\u0647 \u062D\u0633\u06CC \u062F\u0627\u0631\u062F. \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0622\u0646\u0644\u0627\u06CC\u0646 \u06A9\u0645\u06CC \u0647\u0645\u06CC\u0646 \u062D\u0633 \u0631\u0627 \u0628\u0647 \u0634\u0645\u0627 \u0645\u06CC \u062F\u0647\u062F. \u062F\u0631 \u0628\u0631\u062E\u06CC \u0627\u0632 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u060C \u0634\u0645\u0627 \u0627\u06CC\u0646 \u0641\u0631\u0635\u062A \u0631\u0627 \u062F\u0627\u0631\u06CC\u062F \u06A9\u0647 \u062F\u0631 \u0637\u0648\u0644 \u0645\u0633\u06CC\u0631 \u0628\u0627 \u0645\u06CC\u0632\u0628\u0627\u0646 \u0686\u062A \u06A9\u0646\u06CC\u062F. \u0628\u0631\u0627\u06CC \u0628\u0627\u0632\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0632\u0646\u062F\u0647\u060C \u0628\u0633\u062A\u0647 \u0628\u0647 \u0646\u062A\u06CC\u062C\u0647 \u0628\u0627\u0632\u06CC\u060C \u0647\u06CC\u062C\u0627\u0646\u060C \u0634\u0627\u062F\u06CC \u0648 \u0634\u0627\u06CC\u062F \u06A9\u0645\u06CC \u0646\u0627\u0627\u0645\u06CC\u062F\u06CC \u0627\u06CC\u062C\u0627\u062F \u0645\u06CC \u06A9\u0646\u062F.</p>
  <p>\u0627\u06AF\u0631 \u0645\u06CC \u062E\u0648\u0627\u0647\u06CC\u062F \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0632\u0646\u062F\u0647 \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0628\u0627\u06CC\u062F \u062F\u0631 \u06CC\u06A9\u06CC \u0627\u0632 \u0627\u0631\u0627\u0626\u0647 \u062F\u0647\u0646\u062F\u06AF\u0627\u0646 \u0628\u0627\u0632\u06CC \u06A9\u0647 \u0627\u06CC\u0646 \u0631\u0627 \u0627\u0631\u0627\u0626\u0647 \u0645\u06CC \u062F\u0647\u0646\u062F \u062B\u0628\u062A \u0646\u0627\u0645 \u06A9\u0646\u06CC\u062F. \u062B\u0628\u062A \u0646\u0627\u0645 \u062F\u0631 \u06CC\u06A9 \u0634\u0631\u06A9\u062A \u0628\u0627\u0632\u06CC \u0633\u0627\u0632\u06CC \u062E\u0627\u0631\u062C\u06CC \u0622\u0633\u0627\u0646 \u0627\u0633\u062A \u0648 \u0634\u0645\u0627 \u0641\u0642\u0637 \u0627\u0637\u0644\u0627\u0639\u0627\u062A \u062E\u0648\u062F \u0631\u0627 \u062A\u06A9\u0645\u06CC\u0644 \u0645\u06CC \u06A9\u0646\u06CC\u062F. \u067E\u0633 \u0627\u0632 \u0627\u06CC\u0646\u060C \u0628\u06CC\u062A \u06A9\u0648\u06CC\u0646 \u06CC\u0627 \u0634\u06A9\u0644 \u062F\u06CC\u06AF\u0631\u06CC \u0627\u0632 \u067E\u0648\u0644 \u0648\u0627\u0642\u0639\u06CC \u0631\u0627 \u0648\u0627\u0631\u06CC\u0632 \u0645\u06CC \u06A9\u0646\u06CC\u062F \u0648 \u0634\u0631\u0648\u0639 \u0628\u0647 \u0628\u0627\u0632\u06CC \u0645\u06CC \u06A9\u0646\u06CC\u062F.</p>
  <p>\u0628\u0627\u0632\u06CC\u06A9\u0646\u0627\u0646 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0627\u0646\u062A\u0638\u0627\u0631 \u062F\u0627\u0631\u0646\u062F \u06A9\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u060C \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0632\u0646\u062F\u0647 \u0627\u0631\u0627\u0626\u0647 \u062F\u0647\u062F. \u0628\u0627\u0632\u06CC \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0632\u0646\u062F\u0647 \u0622\u0646\u0642\u062F\u0631 \u0631\u0627\u06CC\u062C \u0627\u0633\u062A \u06A9\u0647 \u0647\u0645\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0628\u0627\u06CC\u062F \u0627\u06CC\u0646 \u0631\u0627 \u062F\u0631 \u0645\u062D\u062F\u0648\u062F\u0647 \u062E\u0648\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u0646\u062F.</p>
  <p>\u0627\u0646\u0648\u0627\u0639 \u0645\u062E\u062A\u0644\u0641\u06CC \u0627\u0632 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648\u06CC \u0632\u0646\u062F\u0647 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F \u06A9\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0647 \u0635\u0648\u0631\u062A \u0622\u0646\u0644\u0627\u06CC\u0646 \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F\u060C \u0648 \u0631\u0648\u0644\u062A \u0648 \u0628\u0644\u06A9 \u062C\u06A9 \u0631\u0627\u06CC\u062C \u062A\u0631\u06CC\u0646 \u0634\u06A9\u0644 \u0647\u0627\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0632\u0646\u062F\u0647 \u0647\u0633\u062A\u0646\u062F. \u0627\u0645\u0627 \u0628\u0627\u0632\u06CC \u0647\u0627\u06CC\u06CC \u0645\u0627\u0646\u0646\u062F Monopoly \u0646\u06CC\u0632 \u0648\u062C\u0648\u062F \u062F\u0627\u0631\u062F \u0648 \u0634\u0645\u0627 \u0645\u06CC\u0644\u06CC\u0648\u0646\u0631 \u062E\u0648\u0627\u0647\u06CC\u062F \u0634\u062F \u0648 \u0686\u0631\u062E \u0647\u0627\u06CC\u06CC \u0631\u0627 \u0645\u06CC \u0686\u0631\u062E\u0627\u0646\u06CC\u062F \u06A9\u0647 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u0628\u0647 \u0635\u0648\u0631\u062A \u0632\u0646\u062F\u0647 \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F.</p>
  <p>\u0627\u0646\u062A\u062E\u0627\u0628 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627 \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u06AF\u0633\u062A\u0631\u062F\u0647 \u0627\u0633\u062A\u060C \u0627\u0645\u0627 \u0628\u0627\u06CC\u062F \u0628\u062F\u0627\u0646\u06CC\u062F \u06A9\u0647 \u0627\u0632 \u06CC\u06A9 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0628\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u062F\u06CC\u06AF\u0631 \u0645\u062A\u0641\u0627\u0648\u062A \u0627\u0633\u062A\u060C \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646 \u0647\u0645\u06CC\u0634\u0647 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC \u06A9\u0627\u0632\u06CC\u0646\u0648\u06CC \u06A9\u0631\u06CC\u067E\u062A\u0648 \u06CC\u06A9\u0633\u0627\u0646 \u0631\u0627 \u062F\u0631 \u0633\u0627\u06CC\u062A\u200C\u0647\u0627\u06CC \u0645\u062E\u062A\u0644\u0641 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u06A9\u0631\u06CC\u067E\u062A\u0648 \u0646\u062E\u0648\u0627\u0647\u06CC\u062F \u062F\u0627\u0634\u062A. \u0628\u0647 \u0647\u0645\u06CC\u0646 \u062F\u0644\u06CC\u0644 \u0627\u0633\u062A \u06A9\u0647 \u0628\u0647 \u0634\u0645\u0627 \u0646\u06A9\u0627\u062A\u06CC \u0631\u0627 \u062F\u0631 \u0645\u0648\u0631\u062F \u0627\u06CC\u0646\u06A9\u0647 \u062F\u0631 \u0686\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC\u06CC \u0628\u0627\u06CC\u062F \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F \u06CC\u0627 \u0646\u0647 \u06AF\u0641\u062A\u06CC\u0645\u060C \u0627\u0645\u0627 \u0686\u06AF\u0648\u0646\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u06A9\u0627\u0632\u06CC\u0646\u0648\u06CC \u0645\u0646\u0627\u0633\u0628\u06CC \u0631\u0627 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u062F \u062A\u0627 \u0628\u0647 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u062F \u0646\u06AF\u0627\u0647 \u06A9\u0646\u06CC\u062F.</p>
  <p>\u0648 \u0628\u0647 \u06CC\u0627\u062F \u062F\u0627\u0634\u062A\u0647 \u0628\u0627\u0634\u06CC\u062F \u06A9\u0647 \u0628\u0631\u0631\u0633\u06CC \u06A9\u0646\u06CC\u062F \u0686\u0647 \u0646\u0648\u0639 \u067E\u0627\u062F\u0627\u0634 \u0647\u0627\u06CC\u06CC \u0631\u0627 \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u062F\u0631\u06CC\u0627\u0641\u062A \u06A9\u0646\u06CC\u062F. \u0647\u0645\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627 \u0628\u0647 \u0634\u0645\u0627 \u067E\u0627\u062F\u0627\u0634 \u0648\u0627\u0631\u06CC\u0632 \u0646\u0645\u06CC \u062F\u0647\u0646\u062F\u060C \u0627\u0645\u0627 \u067E\u0627\u062F\u0627\u0634 \u0647\u0627\u06CC \u0628\u0627\u0631\u06AF\u0630\u0627\u0631\u06CC \u0645\u062C\u062F\u062F \u0631\u0627 \u062F\u0631 \u0627\u062E\u062A\u06CC\u0627\u0631 \u0634\u0645\u0627 \u0642\u0631\u0627\u0631 \u0645\u06CC \u062F\u0647\u0646\u062F. \u0628\u0646\u0627\u0628\u0631\u0627\u06CC\u0646\u060C \u0627\u06AF\u0631 \u0642\u0628\u0644 \u0627\u0632 \u0634\u0631\u0648\u0639 \u0628\u0647 \u0627\u0646\u062F\u0627\u0632\u0647 \u06A9\u0627\u0641\u06CC \u062E\u0648\u0628 \u0628\u0631\u0631\u0633\u06CC \u0646\u06A9\u0646\u06CC\u062F\u060C \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u067E\u0627\u062F\u0627\u0634 \u0647\u0627\u06CC \u0628\u0627\u0631\u06AF\u0630\u0627\u0631\u06CC \u0645\u062C\u062F\u062F \u0631\u0627 \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u062F \u0648\u0644\u06CC \u067E\u0627\u062F\u0627\u0634 \u0648\u0627\u0631\u06CC\u0632 \u0631\u0627 \u062E\u06CC\u0631. \u0648 \u0627\u06AF\u0631 \u062E\u0648\u0634 \u0634\u0627\u0646\u0633 \u0628\u0627\u0634\u06CC\u062F\u060C \u0645\u06CC \u062A\u0648\u0627\u0646\u06CC\u062F \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC\u06CC \u0628\u06CC\u0627\u0628\u06CC\u062F \u06A9\u0647 \u0631\u0648\u0632\u0627\u0646\u0647 \u0646\u0642\u062F\u06CC\u0646\u06AF\u06CC \u0631\u0627 \u067E\u0633 \u0645\u06CC \u062F\u0647\u0646\u062F.</p>
  

  <h2>\u0622\u06CC\u0627 \u0645\u06CC \u062A\u0648\u0627\u0646\u0645 \u0627\u0632 \u0645\u0648\u0628\u0627\u06CC\u0644 \u06CC\u0627 \u062A\u0628\u0644\u062A \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u0645\u061F</h2>
  <p>\u0641\u0631\u0636 \u06A9\u0646\u06CC\u062F \u0645\u06CC \u062E\u0648\u0627\u0647\u06CC\u062F \u062F\u0631 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0622\u0646\u0644\u0627\u06CC\u0646 \u0628\u0631\u062A\u0631 \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F. \u062F\u0631 \u0627\u06CC\u0646 \u0635\u0648\u0631\u062A\u060C \u0634\u0645\u0627 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u062F \u06A9\u0647 \u0647\u0645\u0647 \u0622\u0646\u200C\u0647\u0627 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0645\u0648\u0628\u0627\u06CC\u0644 \u0628\u0627\u0634\u0646\u062F\u060C \u0641\u0642\u0637 \u0628\u0631\u0627\u06CC \u0644\u0630\u062A \u062E\u0627\u0644\u0635 \u0627\u0632 \u0628\u0627\u0632\u06CC \u062F\u0631 \u0647\u0631 \u0632\u0645\u0627\u0646 \u0648 \u0647\u0631 \u06A9\u062C\u0627 \u06A9\u0647 \u0647\u0633\u062A\u06CC\u062F \u062F\u0631 \u0632\u0645\u0627\u0646\u06CC \u0627\u0632 \u0631\u0648\u0632 \u06A9\u0647 \u0645\u06CC\u200C\u062E\u0648\u0627\u0647\u06CC\u062F \u0628\u0627\u0632\u06CC \u06A9\u0646\u06CC\u062F.</p>
  <p>\u0633\u0627\u06CC\u062A\u200C\u0647\u0627\u06CC \u0634\u0631\u0637\u200C\u0628\u0646\u062F\u06CC \u06A9\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648\u0647\u0627\u06CC \u0645\u0648\u0628\u0627\u06CC\u0644\u06CC \u0627\u0631\u0627\u0626\u0647 \u0645\u06CC\u200C\u062F\u0647\u0646\u062F\u060C \u062F\u0631 \u06CC\u06A9 \u0631\u0648\u0632 \u0628\u06CC\u0634\u062A\u0631 \u0627\u0632 \u0633\u0627\u06CC\u062A\u200C\u0647\u0627\u06CC\u06CC \u06A9\u0647 \u06A9\u0627\u0632\u06CC\u0646\u0648 \u0645\u0648\u0628\u0627\u06CC\u0644 \u0627\u0631\u0627\u0626\u0647 \u0646\u0645\u06CC\u200C\u062F\u0647\u0646\u062F\u060C \u0628\u0627\u0632\u062F\u06CC\u062F \u0645\u06CC\u200C\u06A9\u0646\u0646\u062F. \u0647\u0645\u0647 \u0645\u0627 \u0645\u06CC\u200C\u062F\u0627\u0646\u06CC\u0645 \u06A9\u0647 \u0647\u06CC\u0686 \u06A9\u0633 \u062F\u06CC\u06AF\u0631 \u0646\u0645\u06CC \u062E\u0648\u0627\u0647\u062F \u0628\u0631\u0627\u06CC \u0642\u0645\u0627\u0631 \u0622\u0646\u0644\u0627\u06CC\u0646 \u062E\u0648\u062F \u062C\u0644\u0648\u06CC \u0644\u067E \u062A\u0627\u067E \u0628\u0646\u0634\u06CC\u0646\u062F. \u0628\u0647\u062A\u0631\u06CC\u0646 \u0686\u06CC\u0632 \u0627\u06CC\u0646 \u0627\u0633\u062A \u06A9\u0647 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u06CC\u062F \u062A\u0645\u0627\u0645 \u0628\u0627\u0632\u06CC\u200C\u0647\u0627\u06CC \u0645\u0646\u0635\u0641\u0627\u0646\u0647 \u0648 \u062C\u0627\u06CC\u0632\u0647 \u062E\u0648\u0634\u200C\u0622\u0645\u062F\u06AF\u0648\u06CC\u06CC \u0641\u0648\u0642\u200C\u0627\u0644\u0639\u0627\u062F\u0647\u200C\u0627\u06CC \u0631\u0627 \u06A9\u0647 \u0645\u0639\u0645\u0648\u0644\u0627\u064B \u062F\u0631 \u0635\u0648\u0631\u062A \u0628\u0627\u0632\u06CC \u0627\u0632 \u0644\u067E\u200C\u062A\u0627\u067E \u0645\u06CC\u200C\u0628\u06CC\u0646\u06CC\u062F\u060C \u067E\u06CC\u062F\u0627 \u06A9\u0646\u06CC\u062F.</p>
</div>`;
